// Auto-generated for the Unit Board (Zone 6: SAT Must-Know 306 + 386)
window.MK_DASHBOARD_UNITS = [{"unit":1,"theme":"abate – adapt","cards":[{"w":"abate","p":"v.","d":"To become less active, less intense, or less in amount.","c":"減弱；緩和","s":"As I began my speech, my feelings of nervousness quickly abated.","t":"我開始演講時，緊張的感覺很快就減弱了。","src":"386"},{"w":"abhor","p":"v.","d":"To regard with disgust and hatred.","c":"憎惡；厭惡","s":"She abhors violence and prefers peaceful solutions.","t":"她厭惡暴力，偏好和平的解決方式。","src":"306"},{"w":"abrasive","p":"adj.","d":"Showing little concern for others; harsh.","c":"粗暴的；刺耳的","s":"His abrasive remarks alienated his coworkers.","t":"他尖酸刺耳的話語疏遠了同事。","src":"306"},{"w":"abrupt","p":"adj.","d":"Sudden or unexpected; brief and curt in manner.","c":"突然的；唐突的","s":"His abrupt departure left everyone shocked and confused.","t":"他的突然離開讓每個人既震驚又困惑。","src":"306 + 386"},{"w":"absolve","p":"v.","d":"To free someone from blame, guilt, or responsibility.","c":"免除罪責；赦免","s":"The jury absolved her of all wrongdoing.","t":"陪審團免除了她所有的罪責。","src":"306"},{"w":"abstain","p":"v.","d":"To restrain oneself from doing or enjoying something.","c":"戒絕；棄權","s":"He abstained from eating dessert to maintain his diet.","t":"為了維持飲食，他忍住不吃甜點。","src":"306"},{"w":"abstract","p":"adj.","d":"Existing purely in the mind; not representing actual reality.","c":"抽象的","s":"Julie had trouble understanding the appeal of the abstract painting.","t":"茱莉很難理解那幅抽象畫的魅力所在。","src":"386"},{"w":"abundance","p":"n.","d":"A large quantity of something; more than enough.","c":"豐富；充足","s":"The region is known for its abundance of natural resources.","t":"這個地區以豐富的天然資源聞名。","src":"306"},{"w":"abundant","p":"adj.","d":"Existing or available in large quantities.","c":"豐富的；充足的","s":"The region is known for its abundant natural resources.","t":"這個地區以豐富的天然資源聞名。","src":"306"},{"w":"abysmal","p":"adj.","d":"Extremely bad.","c":"糟糕透頂的","s":"I got an abysmal grade on my research paper!","t":"我的研究報告拿到了糟透了的分數！","src":"386"},{"w":"accentuate","p":"v.","d":"To emphasize or highlight.","c":"強調；使突出","s":"The design accentuates the modern features of the building.","t":"這個設計突顯了建築物的現代特色。","src":"306"},{"w":"acceptable","p":"adj.","d":"Satisfactory or permissible.","c":"可接受的","s":"The teacher deemed Sara's late assignment acceptable.","t":"老師認為莎拉遲交的作業還可以接受。","src":"386"},{"w":"accessible","p":"adj.","d":"Easy to approach or reach; capable of being used or understood.","c":"易取得的；易接近的；易懂的","s":"The new website is much more accessible than the old one.","t":"新網站比舊網站更容易使用。","src":"306"},{"w":"accidental","p":"adj.","d":"Happening by chance.","c":"意外的；偶然的","s":"The oil spill was purely accidental.","t":"那次漏油事件純屬意外。","src":"386"},{"w":"accommodate","p":"v.","d":"To provide space or make adjustments.","c":"容納；適應","s":"The Grand Hotel can accommodate up to 500 guests.","t":"大飯店最多可容納五百位客人。","src":"386"},{"w":"accuracy","p":"n.","d":"The quality of being correct or precise.","c":"準確性","s":"The accuracy of the intern's report was impressive.","t":"實習生報告的準確度令人印象深刻。","src":"386"},{"w":"acknowledge","p":"v.","d":"To recognize or admit the truth.","c":"承認；答謝","s":"She refused to acknowledge her mistake.","t":"她拒絕承認自己的錯誤。","src":"386"},{"w":"acquired","p":"adj.","d":"Gained through effort or experience.","c":"習得的；後天獲得的","s":"Edmund had acquired a taste for fine wine.","t":"艾德蒙已經培養出品嚐好酒的品味。","src":"386"},{"w":"adamant","p":"adj.","d":"Refusing to be persuaded or change one’s mind.","c":"固執的；堅定不移的","s":"She was adamant about finishing the project on time, despite obstacles.","t":"儘管困難重重，她仍堅決要準時完成這個計畫。","src":"306"},{"w":"adapt","p":"v.","d":"To adjust to new conditions.","c":"適應","s":"Newly-released animals generally adapt to their environments over time.","t":"剛被野放的動物通常會隨著時間適應環境。","src":"386"}]},{"unit":2,"theme":"adept – ambivalent","cards":[{"w":"adept","p":"adj.","d":"Very skilled or proficient at something.","c":"熟練的；精通的","s":"He is adept at solving complex math problems.","t":"他擅長解複雜的數學題。","src":"306 + 386"},{"w":"adequate","p":"adj.","d":"Having sufficient qualifications to meet a specific task or purpose.","c":"足夠的；適當的","s":"Though his resume was adequate, the company doubted whether he’d be a good fit.","t":"雖然他的履歷還算合格，公司仍懷疑他是否適合。","src":"386"},{"w":"adhere","p":"v.","d":"To stick firmly to a surface or to follow a set of rules or beliefs.","c":"黏附；遵守","s":"The paint adheres well to the wood surface. The artist chose to adhere strictly to the classical style of painting.","t":"油漆能牢牢附著在木頭表面。這位藝術家選擇嚴格遵守古典的繪畫風格。","src":"306 + 386"},{"w":"adjust","p":"v.","d":"To modify or change slightly.","c":"調整","s":"He had to adjust his seat for comfort.","t":"為了坐得舒服，他必須調整座椅。","src":"386"},{"w":"admire","p":"v.","d":"To respect or look up to.","c":"欽佩；仰慕","s":"I admire my mother's dedication to her work.","t":"我欽佩媽媽對工作的投入。","src":"386"},{"w":"admonish","p":"v.","d":"To warn or reprimand someone firmly.","c":"警告；勸誡","s":"The teacher admonished the students for not completing their homework.","t":"老師告誡學生沒有完成作業。","src":"306"},{"w":"advantageous","p":"adj.","d":"Beneficial or useful.","c":"有利的","s":"Speaking multiple languages is advantageous.","t":"會說多種語言是有利的。","src":"386"},{"w":"advent","p":"n.","d":"The arrival or creation of something.","c":"到來；出現","s":"The world has never been the same since the advent of the light bulb.","t":"自從電燈泡問世以來，世界就不再一樣了。","src":"386"},{"w":"advise","p":"v.","d":"To recommend or give guidance.","c":"建議；勸告","s":"I advise you to study for the exam.","t":"我建議你為考試好好讀書。","src":"386"},{"w":"affable","p":"adj.","d":"Friendly, good-natured, or easy to talk to.","c":"和藹可親的；平易近人的","s":"His affable demeanor made him popular among his peers.","t":"他和藹可親的態度讓他在同儕間很受歡迎。","src":"306"},{"w":"affirm","p":"v.","d":"To state as a fact; to declare strongly.","c":"肯定；確認","s":"The witness affirmed that she saw the suspect at the scene.","t":"證人斷言她在現場看到了嫌犯。","src":"306"},{"w":"aggravate","p":"v.","d":"To worsen or intensify.","c":"使惡化；加重","s":"Scratching the rash will only aggravate it.","t":"抓癢只會讓疹子更加惡化。","src":"386"},{"w":"aggressive","p":"adj.","d":"Forceful or overly assertive.","c":"好鬥的；積極進取的","s":"The man's aggressive tone made everyone uneasy.","t":"那個男人咄咄逼人的語氣讓大家都很不安。","src":"386"},{"w":"agitate","p":"v.","d":"To stir or disturb emotionally or physically.","c":"攪動；使不安","s":"The loud noises agitated the baby, causing her to cry.","t":"巨大的噪音讓嬰兒焦躁不安，哭了起來。","src":"306"},{"w":"allude","p":"v.","d":"To make a secretive mention of something.","c":"暗示；間接提及","s":"She alluded to the problem at hand but didn’t say anything more about it.","t":"她暗示了眼前的問題，但沒有再多說什麼。","src":"386"},{"w":"alternating","p":"adj.","d":"Occurring in turns or rotation; switching back and forth between different states or actions.","c":"交替的；輪流的","s":"The alternating patterns of light and dark made the room feel dynamic.","t":"明暗交替的圖案讓房間顯得很有動感。","src":"306"},{"w":"ambiguity","p":"n.","d":"Uncertainty or multiple interpretations.","c":"模糊性；含糊不清","s":"The ambiguity in his vague statement caused confusion.","t":"他含糊陳述中的模稜兩可造成了混亂。","src":"386"},{"w":"ambiguous","p":"adj.","d":"Open to more than one interpretation; unclear.","c":"模稜兩可的","s":"The politician’s ambiguous statement left voters confused.","t":"那位政治人物模稜兩可的聲明讓選民感到困惑。","src":"306"},{"w":"ambivalence","p":"n.","d":"Mixed or conflicting feelings.","c":"矛盾情感；猶豫不決","s":"Jessie felt ambivalence about moving to a new city.","t":"潔西對搬到新城市感到矛盾。","src":"386"},{"w":"ambivalent","p":"adj.","d":"Having mixed or contradictory feelings about something.","c":"矛盾的；猶豫不決的","s":"She felt ambivalent about moving to a new city—excited but also apprehensive.","t":"她對搬到新城市感到矛盾──既興奮又不安。","src":"306"}]},{"unit":3,"theme":"ameliorate – arouse","cards":[{"w":"ameliorate","p":"v.","d":"To improve or make better.","c":"改善；減輕","s":"The new policy aims to ameliorate working conditions for all employees.","t":"新政策旨在改善全體員工的工作條件。","src":"386"},{"w":"amiable","p":"adj.","d":"Having or displaying a friendly and pleasant manner.","c":"友善的；和藹的","s":"Her amiable personality made her well-liked by everyone.","t":"她和藹可親的個性讓她受到大家喜愛。","src":"306"},{"w":"amplify","p":"v.","d":"To increase the volume or intensity of something.","c":"放大；增強","s":"The speaker amplified his voice to address the large crowd.","t":"演講者放大了聲音，向廣大的群眾說話。","src":"306 + 386"},{"w":"amusing","p":"adj.","d":"Entertaining or humorous.","c":"有趣的；好笑的","s":"Jason's joke was quite amusing.","t":"傑森的笑話相當有趣。","src":"386"},{"w":"analogous","p":"adj.","d":"Similar but not identical.","c":"類似的；可類比的","s":"Green onions are considered analogous to spring onions.","t":"青蔥被認為和春蔥相似。","src":"386"},{"w":"animosity","p":"n.","d":"Strong hostility or dislike.","c":"敵意；仇恨","s":"There was clear animosity between the rival teams.","t":"兩支敵對的隊伍之間有明顯的敵意。","src":"306"},{"w":"annotate","p":"v.","d":"To add explanatory notes or comments to a text or diagram.","c":"加註解；註釋","s":"The teacher asked us to annotate the passage with notes about its themes.","t":"老師要我們在文章上加註，寫下關於主題的筆記。","src":"306 + 386"},{"w":"announce","p":"v.","d":"To make a public statement.","c":"宣布；公告","s":"The CEO will announce the new policy tomorrow.","t":"執行長明天將宣布新政策。","src":"386"},{"w":"anomaly","p":"n.","d":"Something different from the norm.","c":"異常；反常","s":"This result is an anomaly and very rarely happens.","t":"這個結果是個異常現象，極少發生。","src":"386"},{"w":"antagonistic","p":"adj.","d":"Showing hostility or opposition.","c":"敵對的；對抗性的","s":"His antagonistic behavior created tension at work.","t":"他充滿敵意的行為在職場上造成了緊張氣氛。","src":"386"},{"w":"antecedent","p":"n.","d":"A preceding event or condition.","c":"前因；先例","s":"The antecedent to the war was political unrest.","t":"這場戰爭的先前起因是政治動盪。","src":"386"},{"w":"anticipate","p":"v.","d":"To expect or predict.","c":"預期；期待","s":"Does the weatherman anticipate a rise in temperatures next week?","t":"氣象播報員預期下週氣溫會上升嗎？","src":"386"},{"w":"antipathy","p":"n.","d":"A strong feeling of dislike.","c":"反感；厭惡","s":"Her antipathy toward the professor was obvious: she rolled her eyes whenever he entered the classroom.","t":"她對那位教授的反感很明顯：每當他走進教室，她就翻白眼。","src":"386"},{"w":"apex","p":"n.","d":"The highest point of something.","c":"頂點；最高點；巔峰","s":"The spring play was the apex of our school year.","t":"春季戲劇是我們這一學年的最高潮。","src":"386"},{"w":"appropriate","p":"adj.","d":"Suitable for a specific situation.","c":"適當的；合宜的","s":"Lily's velvet dress was appropriate for the formal occasion.","t":"莉莉的天鵝絨洋裝很適合正式場合。","src":"386"},{"w":"approximate","p":"adj./v.","d":"Close to the actual, but not completely accurate or exact.","c":"大概的；近似的","s":"The approximate distance between the two cities is 200 miles.","t":"兩座城市之間的大約距離是兩百英里。","src":"306 + 386"},{"w":"arcane","p":"adj.","d":"Mysterious or known by few.","c":"神秘的；隱奧的","s":"The ancient book contained arcane knowledge.","t":"那本古書裡記載著深奧難懂的知識。","src":"386"},{"w":"ardent","p":"adj.","d":"Enthusiastic or passionate.","c":"熱烈的；激情的","s":"She was an ardent supporter of the environmental movement.","t":"她是環保運動的熱情支持者。","src":"306"},{"w":"arduous","p":"adj.","d":"Difficult and requiring effort.","c":"艱辛的；費力的","s":"The steep hike up the mountain was arduous.","t":"爬上那座山的陡峭步道非常艱辛。","src":"386"},{"w":"arouse","p":"v.","d":"To awaken or stimulate a feeling or response; to provoke.","c":"喚起；激起","s":"The announcement aroused a sense of excitement in the audience.","t":"這項宣布在觀眾之間激起了一股興奮感。","src":"306"}]},{"unit":4,"theme":"articulate – candid","cards":[{"w":"articulate","p":"v.","d":"To express an idea or feeling clearly.","c":"清楚表達","s":"The professor articulated his ideas with precision and clarity.","t":"教授精確而清楚地表達了他的想法。","src":"306"},{"w":"ascertain","p":"v.","d":"To find out for certain.","c":"查明；確定","s":"The detective worked to ascertain the facts of the case.","t":"警探努力查明案件的真相。","src":"306"},{"w":"assemble","p":"v.","d":"To gather or put together.","c":"集合；組裝","s":"We need to assemble the bed if we want a place to sleep tonight.","t":"如果今晚想有地方睡，我們得把床組裝好。","src":"386"},{"w":"assert","p":"v.","d":"To state or declare something confidently or forcefully.","c":"斷言；主張","s":"He asserted his innocence in the face of the accusations.","t":"面對指控，他堅稱自己是清白的。","src":"306"},{"w":"atypical","p":"adj.","d":"Not typical; unusual or uncommon.","c":"非典型的","s":"The artist’s work was considered atypical for its time, breaking conventional norms.","t":"這位藝術家的作品在當時被認為不尋常，打破了傳統規範。","src":"306"},{"w":"audacious","p":"adj.","d":"Bold, daring, or showing a lack of respect.","c":"大膽的；無畏的","s":"His audacious plan to climb the mountain without gear shocked everyone.","t":"他打算不帶裝備就攀登那座山，這個大膽的計畫震驚了所有人。","src":"306"},{"w":"augment","p":"v.","d":"To make something greater by adding to it.","c":"增加；擴大","s":"She took on a second job to augment her income.","t":"她兼了第二份工作來增加收入。","src":"306"},{"w":"austere","p":"adj.","d":"Severe or strict in manner, attitude, or appearance.","c":"嚴峻的；簡樸的","s":"The monk’s austere lifestyle contrasted with the lavish surroundings.","t":"那位僧侶簡樸的生活方式和奢華的環境形成對比。","src":"306 + 386"},{"w":"avoid","p":"v.","d":"To stay away from or prevent.","c":"避免；躲避","s":"Mara hates fighting, so she always tries to avoid conflict.","t":"瑪拉討厭吵架，所以她總是設法避免衝突。","src":"386"},{"w":"beneficial","p":"adj.","d":"Producing good results.","c":"有益的；有利的","s":"A balanced diet is beneficial to your health.","t":"均衡飲食對健康有益。","src":"386"},{"w":"benevolent","p":"adj.","d":"Well-meaning and kind.","c":"仁慈的；慈善的","s":"Her benevolent gestures earned her the admiration of the community.","t":"她樂善好施的舉動贏得了社區的敬佩。","src":"306 + 386"},{"w":"bold","p":"adj.","d":"Courageous or striking.","c":"大膽的","s":"Elsie made a bold move by quitting her job.","t":"艾爾西辭掉工作，做了一個大膽的決定。","src":"386"},{"w":"bolster","p":"v.","d":"To support or strengthen.","c":"支持；加強","s":"The coach’s pep talk bolstered the team’s morale.","t":"教練的打氣談話提振了球隊的士氣。","src":"306"},{"w":"bombastic","p":"adj.","d":"High-sounding but with little meaning; inflated.","c":"誇誇其談的；浮誇的","s":"His bombastic speech failed to convey a clear message.","t":"他浮誇的演講沒能傳達明確的訊息。","src":"306"},{"w":"borrow","p":"v.","d":"To take temporarily.","c":"借","s":"Libraries will let you borrow books for several weeks.","t":"圖書館會讓你借書好幾週。","src":"386"},{"w":"brash","p":"adj.","d":"Self-assertive in a rude or overbearing way.","c":"傲慢的；魯莽的","s":"His brash behavior alienated potential allies.","t":"他魯莽無禮的行為疏遠了潛在的盟友。","src":"306"},{"w":"buttress","p":"n./v.","d":"A structure built to support or reinforce a wall or building; to support or strengthen something.","c":"支柱；支撐","s":"The church’s walls were buttressed with large stone supports.","t":"教堂的牆壁用巨大的石頭支柱加以支撐。","src":"306 + 386"},{"w":"bypass","p":"v.","d":"To go around or avoid.","c":"繞過；避開；旁路","s":"We took a shortcut to bypass traffic.","t":"我們抄捷徑來避開車潮。","src":"386"},{"w":"calibrate","p":"v.","d":"To adjust for precision.","c":"校準","s":"The scientist had to calibrate the instrument to ensure his measurements were accurate.","t":"科學家必須校準儀器，以確保測量準確。","src":"386"},{"w":"candid","p":"adj.","d":"Truthful and straightforward.","c":"坦白的；直率的","s":"She gave a candid assessment of her colleague's performance.","t":"她對同事的表現給了坦率的評價。","src":"306 + 386"}]},{"unit":5,"theme":"capitulate – compose","cards":[{"w":"capitulate","p":"v.","d":"To cease to resist an opponent or surrender.","c":"投降；屈服","s":"The enemy was forced to capitulate after weeks of siege.","t":"經過數週的圍城，敵軍被迫投降。","src":"306"},{"w":"carelessly","p":"adv.","d":"Without caution.","c":"粗心地；不小心地","s":"He carelessly left his keys on the bus.","t":"他粗心地把鑰匙忘在公車上。","src":"386"},{"w":"catastrophic","p":"adj.","d":"Involving or causing great damage or disaster.","c":"災難性的","s":"The earthquake had catastrophic consequences for the local population.","t":"這場地震對當地居民造成了災難性的後果。","src":"306 + 386"},{"w":"cause","p":"n.","d":"A reason for an action or event.","c":"原因","s":"The fire's cause is still unknown.","t":"火災的起因仍然不明。","src":"386"},{"w":"characterization","p":"n.","d":"The way a character is described.","c":"人物刻畫；描述","s":"The novel's characterization was deep and complex.","t":"這本小說的人物塑造深刻而複雜。","src":"386"},{"w":"circumvent","p":"v.","d":"To find a way around an obstacle or restriction; to avoid by cleverness.","c":"規避；繞過","s":"The company tried to circumvent the new regulations by finding loopholes.","t":"這家公司試圖找漏洞來規避新法規。","src":"306 + 386"},{"w":"coerce","p":"v.","d":"To persuade someone forcefully to do something.","c":"強制；脅迫","s":"They coerced the witness into giving false testimony.","t":"他們脅迫證人作出偽證。","src":"306"},{"w":"cognitive","p":"adj.","d":"Relating to the mental processes of perception, memory, judgment, and reasoning.","c":"認知的","s":"Cognitive development is essential for young children as they learn new skills.","t":"認知發展對正在學習新技能的幼童至關重要。","src":"306"},{"w":"cognizant","p":"adj.","d":"Having knowledge or awareness.","c":"認識到的；知曉的","s":"He is fully cognizant of the risks involved in this venture.","t":"他完全意識到這項投資所涉及的風險。","src":"306"},{"w":"coincidence","p":"n.","d":"A surprising and unexpected event.","c":"巧合","s":"Meeting my neighbor at the airport was a coincidence.","t":"在機場遇到鄰居真是巧合。","src":"386"},{"w":"collaboration","p":"n.","d":"Working together on a task.","c":"合作","s":"The scientists' collaboration led to a breakthrough.","t":"科學家們的合作帶來了突破。","src":"386"},{"w":"commercialization","p":"n.","d":"The process of making something a business.","c":"商業化","s":"The commercialization of the product increased sales.","t":"這項產品的商業化提升了銷售量。","src":"386"},{"w":"commercialize","p":"v.","d":"To manage or exploit something for financial gain; to turn into a commercial product or activity.","c":"使商業化","s":"The company plans to commercialize its new technology by next year.","t":"這家公司計畫在明年以前將新技術商業化。","src":"306"},{"w":"committed","p":"adj.","d":"Dedicated to a cause or task.","c":"投入的；忠誠的","s":"Ava is committed to her studies and always wants top grades.","t":"艾娃致力於學業，總是想拿最高分。","src":"386"},{"w":"common","p":"adj.","d":"Occurring frequently or shared.","c":"常見的","s":"It's very common for students to feel stressed before exams.","t":"學生在考試前感到壓力是很常見的。","src":"386"},{"w":"compelling","p":"adj.","d":"Captivating or persuasive.","c":"引人入勝的；有說服力的","s":"The debater gave a compelling argument.","t":"這位辯手提出了令人信服的論點。","src":"386"},{"w":"competent","p":"adj.","d":"Having the necessary ability or skill.","c":"有能力的；勝任的","s":"Noah has worked at this job for a long time and is a competent engineer.","t":"諾亞在這份工作上做了很久，是一位能幹的工程師。","src":"386"},{"w":"complementary","p":"adj.","d":"Combining in such a way as to enhance or complete something.","c":"互補的；相輔相成的","s":"Their talents were complementary, making them an ideal team.","t":"他們的才能互補，讓他們成為理想的團隊。","src":"306 + 386"},{"w":"complexity","p":"n.","d":"The state of being intricate or complicated.","c":"複雜性","s":"The complexity of the 1,000 piece puzzle made it challenging.","t":"這幅一千片拼圖的複雜度讓它很有挑戰性。","src":"386"},{"w":"compose","p":"v.","d":"To create or form something, especially in writing or music; to arrange parts into a whole.","c":"組成；創作","s":"She composed a beautiful symphony that was performed worldwide.","t":"她創作了一首美麗的交響曲，在世界各地演出。","src":"306 + 386"}]},{"unit":6,"theme":"compound – contingent","cards":[{"w":"compound","p":"v.","d":"To intensify or combine.","c":"使增加；加重；混合","s":"The traffic was compounded by bad weather.","t":"壞天氣讓交通更加惡化。","src":"386"},{"w":"comprise","p":"v.","d":"To consist of or include.","c":"由...組成；包含","s":"The book comprises ten chapters.","t":"這本書由十個章節組成。","src":"386"},{"w":"conceal","p":"v.","d":"To hide or keep something out of sight.","c":"隱藏","s":"He tried to conceal his disappointment, but it was obvious.","t":"他試圖隱藏失望，但還是很明顯。","src":"306 + 386"},{"w":"concede","p":"v.","d":"To admit or acknowledge something, often reluctantly or after initial resistance.","c":"承認；讓步","s":"After much debate, he conceded that his opponent had a stronger argument.","t":"經過一番辯論，他承認對手的論點比較有力。","src":"306 + 386"},{"w":"conceptualize","p":"v.","d":"To form a concept or idea of something in one’s mind.","c":"構思；使概念化","s":"She conceptualized a new business model that revolutionized the industry.","t":"她構思出一種顛覆整個產業的新商業模式。","src":"306 + 386"},{"w":"concerning","p":"adj.","d":"Causing worry or distress.","c":"令人擔憂的","s":"The news about the approaching hurricane is quite concerning.","t":"關於颶風逼近的消息相當令人擔憂。","src":"386"},{"w":"concise","p":"adj.","d":"Brief but comprehensive.","c":"簡潔的；簡明的","s":"Her presentation was concise and straight to the point.","t":"她的報告簡潔扼要，直切重點。","src":"306"},{"w":"condition","p":"n.","d":"The state of something.","c":"狀態；情況","s":"The car I bought is in excellent condition.","t":"我買的那輛車狀況極佳。","src":"386"},{"w":"confident","p":"adj.","d":"Feeling sure or self-assured.","c":"有信心的","s":"Michael Jordan is confident in his abilities as a basketball player.","t":"麥可・喬丹對自己身為籃球員的能力很有自信。","src":"386"},{"w":"configure","p":"v.","d":"To arrange or set up something in a particular way.","c":"設定；配置","s":"You need to configure the software settings before use.","t":"使用前你需要先設定軟體。","src":"306"},{"w":"conflated","p":"adj.","d":"Combined in a misleading way.","c":"混淆合併的","s":"The two issues were conflated in the argument.","t":"這兩個議題在論證中被混為一談。","src":"386"},{"w":"conform","p":"v.","d":"To comply with rules or expectations.","c":"順從；遵從","s":"The alternative rocker refuses to conform to societal norms.","t":"那位另類搖滾歌手拒絕順從社會規範。","src":"386"},{"w":"consensus","p":"n.","d":"General agreement.","c":"共識","s":"The team finally reached a consensus on the decision.","t":"團隊終於對這項決定達成共識。","src":"386"},{"w":"consistent","p":"adj.","d":"Acting in the same way over time.","c":"一致的；前後一致的","s":"My grandmother's knitting is always consistent in quality.","t":"我祖母織的東西品質總是很一致。","src":"386"},{"w":"conspicuous","p":"adj.","d":"Easily noticed or standing out.","c":"顯眼的；引人注目的","s":"Veronica's red dress was conspicuous in the crowd.","t":"維若妮卡的紅洋裝在人群中十分顯眼。","src":"386"},{"w":"constant","p":"adj.","d":"Occurring continuously.","c":"持續不斷的","s":"The criminal lived in constant fear that he'd be found out.","t":"那名罪犯一直活在會被發現的恐懼之中。","src":"386"},{"w":"consult","p":"v.","d":"To seek advice or information from someone or something.","c":"諮詢","s":"He consulted with his lawyer before making the final decision.","t":"在做最後決定前，他先諮詢了律師。","src":"306"},{"w":"consume","p":"v.","d":"To use up or destroy something; to eat or drink something.","c":"消耗；食用","s":"They consumed the entire pizza within minutes.","t":"他們幾分鐘內就吃光了一整個披薩。","src":"306"},{"w":"contentious","p":"adj.","d":"Causing disagreement or debate.","c":"引起爭議的；好爭論的","s":"Politics are highly contentious these days.","t":"近來政治是極具爭議的話題。","src":"386"},{"w":"contingent","p":"adj.","d":"Dependent on something else.","c":"視情況而定的；偶然的","s":"Our family ski trip is contingent on the weather.","t":"我們家的滑雪之旅要視天氣而定。","src":"386"}]},{"unit":7,"theme":"contoured – debilitate","cards":[{"w":"contoured","p":"adj.","d":"Shaped or formed into a particular outline, especially one that is smooth or curved.","c":"具輪廓的；曲線形的","s":"The contoured surface of the chair made it very comfortable.","t":"椅子符合人體曲線的表面讓它坐起來很舒服。","src":"306"},{"w":"contradict","p":"v.","d":"To be in contrast with.","c":"反駁；矛盾","s":"The camera footage contradicts his alibi.","t":"監視器畫面與他的不在場證明互相矛盾。","src":"386"},{"w":"contrive","p":"v.","d":"To plan or devise something, often in a clever or creative manner.","c":"策劃；設計","s":"They contrived an ingenious plan to surprise their friend on her birthday.","t":"他們想出一個巧妙的計畫，要在朋友生日時給她驚喜。","src":"306"},{"w":"contrived","p":"adj.","d":"Artificial or overly planned.","c":"做作的；牽強的","s":"The movie's plot felt contrived and unrealistic.","t":"這部電影的情節感覺很做作，不真實。","src":"386"},{"w":"controversial","p":"adj.","d":"Causing public disagreement.","c":"有爭議的","s":"The judge's decision to free the criminal was highly controversial.","t":"法官釋放那名罪犯的判決極具爭議。","src":"386"},{"w":"convert","p":"v.","d":"To change something into a different form, state, or use.","c":"轉變；使轉換","s":"He decided to convert his garage into a home office.","t":"他決定把車庫改裝成家庭辦公室。","src":"306"},{"w":"convey","p":"v.","d":"To communicate or transport something from one place to another.","c":"傳達；運送","s":"The letter conveyed a sense of urgency and concern.","t":"這封信傳達出一種急迫和擔憂的感覺。","src":"306"},{"w":"convoluted","p":"adj.","d":"Extremely complex and difficult to follow.","c":"錯綜複雜的；難懂的","s":"The convoluted explanation left everyone confused.","t":"那個錯綜複雜的解釋讓每個人都很困惑。","src":"306"},{"w":"copious","p":"adj.","d":"Abundant in supply or quantity.","c":"豐富的；大量的","s":"The farmer had a copious harvest this year.","t":"這位農夫今年收成豐碩。","src":"306"},{"w":"cordially","p":"adv.","d":"In a warm or friendly manner.","c":"誠摯地；友好地","s":"The two old friends greeted each other cordially.","t":"兩位老朋友熱誠地互相問候。","src":"386"},{"w":"correlates","p":"v.","d":"To show a mutual relationship or connection between two things.","c":"相關；有關聯","s":"The rise in temperature correlates with the increase in energy consumption.","t":"氣溫上升與能源消耗增加互相關聯。","src":"306"},{"w":"corroborate","p":"v.","d":"To provide evidence for; to back up (a claim).","c":"證實；確證","s":"The note signed by her father corroborates her claim that she was absent from class that day.","t":"她父親簽名的字條證實了她那天沒來上課的說法。","src":"386"},{"w":"corrosive","p":"adj.","d":"Gradually destructive or harmful.","c":"腐蝕性的","s":"The corrosive chemical has ruined the paint on my car.","t":"那種腐蝕性化學物質毀了我車子的烤漆。","src":"386"},{"w":"costly","p":"adj.","d":"Expensive or requiring sacrifice.","c":"昂貴的；代價高的","s":"The mistake was a costly one and caused the company to go bankrupt.","t":"這個錯誤代價高昂，讓公司因此破產。","src":"386"},{"w":"counteract","p":"v.","d":"To work in opposition to.","c":"抵消；抵銷","s":"This ingredient seems to counteract the other ones.","t":"這種成分似乎會抵銷其他成分的作用。","src":"386"},{"w":"critical","p":"adj.","d":"Extremely important; essential for a particular purpose; involving an analysis or judgment.","c":"至關重要的；批判性的","s":"It is critical that you submit the report by Friday.","t":"你務必在星期五前交出報告。","src":"306 + 386"},{"w":"criticize","p":"v.","d":"To express disapproval.","c":"批評","s":"My father tends to criticize others harshly.","t":"我父親常常嚴厲地批評別人。","src":"386"},{"w":"cultivate","p":"v.","d":"To grow or nurture something, especially crops or skills.","c":"培養；耕種","s":"He cultivated a passion for reading during his childhood.","t":"他在童年時培養了對閱讀的熱愛。","src":"306"},{"w":"daunt","p":"v.","d":"To make someone feel intimidated or apprehensive.","c":"使膽怯；使畏縮","s":"The steep mountain did not daunt the experienced climber.","t":"陡峭的山並沒有嚇倒那位經驗豐富的登山者。","src":"306"},{"w":"debilitate","p":"v.","d":"To weaken or make something less effective.","c":"使衰弱","s":"The illness debilitated him, leaving him bedridden for weeks.","t":"這場病讓他虛弱不堪，臥床好幾個星期。","src":"306"}]},{"unit":8,"theme":"deceptive – devise","cards":[{"w":"deceptive","p":"adj.","d":"Misleading or giving a false impression.","c":"有欺騙性的；誤導性的","s":"The advertisement was deceptive, leading customers to believe the product was free.","t":"這則廣告具有誤導性，讓顧客以為產品是免費的。","src":"306 + 386"},{"w":"deciding","p":"adj.","d":"Determining or influencing an outcome.","c":"決定性的","s":"The final goal was the deciding factor in the match.","t":"最後一球是這場比賽的決定性因素。","src":"386"},{"w":"decisive","p":"adj.","d":"Conclusive or firm.","c":"果斷的；決定性的","s":"My boss's decisive leadership helped solve our company's crisis.","t":"老闆果斷的領導幫助公司度過了危機。","src":"386"},{"w":"deficient","p":"adj.","d":"Not enough in degree or amount.","c":"不足的；缺乏的","s":"I feel as though the sources for my paper are deficient.","t":"我覺得我報告的參考資料不夠充分。","src":"386"},{"w":"definitive","p":"adj.","d":"Conclusive and authoritative; final.","c":"決定性的；權威的","s":"The dictionary is the definitive source for spelling and definitions.","t":"字典是拼字和定義的權威來源。","src":"306"},{"w":"deft","p":"adj.","d":"Neatly skillful and quick in one’s movements.","c":"靈巧的；熟練的","s":"The pianist’s deft fingers danced across the keys.","t":"鋼琴家靈巧的手指在琴鍵上飛舞。","src":"306"},{"w":"defunct","p":"adj.","d":"No longer existing or functional.","c":"不復存在的；已廢棄的","s":"After people stopped using fax machines, the fax company became defunct.","t":"人們不再使用傳真機後，那家傳真公司就倒閉了。","src":"386"},{"w":"delegate","p":"v.","d":"To assign responsibility or authority to another person or group.","c":"委派；授權","s":"She delegated the task to her assistant, trusting them to handle it efficiently.","t":"她把任務委派給助理，相信對方能有效率地處理。","src":"306 + 386"},{"w":"deliberate","p":"adj.","d":"Done consciously and intentionally.","c":"故意的；深思熟慮的","s":"The deliberate actions of the protestors drew widespread attention.","t":"抗議者蓄意的行動引起了廣泛的關注。","src":"306"},{"w":"deliberation","p":"n.","d":"Careful consideration or discussion.","c":"深思熟慮；商議","s":"After much deliberation, they made their decision.","t":"經過一番深思熟慮，他們做出了決定。","src":"386"},{"w":"delicate","p":"adj.","d":"Fragile or requiring careful handling.","c":"脆弱的；精緻的","s":"The delicate glass sculpture broke easily.","t":"那座精緻的玻璃雕塑很容易就破了。","src":"386"},{"w":"demarcate","p":"v.","d":"To set boundaries or distinguish.","c":"劃定界線；區分","s":"The Tornio river demarcates the border between Sweden and Finland.","t":"托爾尼奧河劃定了瑞典與芬蘭之間的邊界。","src":"386"},{"w":"depict","p":"v.","d":"To represent or portray something through words, pictures, or other forms.","c":"描繪；描述","s":"The artist depicted the landscape with stunning detail.","t":"這位畫家以驚人的細節描繪了那片風景。","src":"306"},{"w":"derived","p":"adj.","d":"Obtained or developed from a source.","c":"衍生出的；源自的","s":"The word \"aqua\" is derived from Latin.","t":"「aqua」這個字源自拉丁文。","src":"386"},{"w":"descend","p":"v.","d":"To move downward; to slope or fall to a lower position.","c":"下降；降落","s":"The hikers began to descend the mountain after reaching the summit.","t":"登頂之後，登山客開始下山。","src":"306"},{"w":"despise","p":"v.","d":"To strongly dislike or look down upon.","c":"鄙視；厭惡","s":"The judge despises dishonesty.","t":"這位法官鄙視不誠實。","src":"386"},{"w":"desultory","p":"adj.","d":"Lacking a clear plan or enthusiasm.","c":"散漫的；斷斷續續的","s":"The tired boy's desultory efforts did not impress the coach.","t":"那個疲憊男孩散漫的努力沒能打動教練。","src":"386"},{"w":"determine","p":"v.","d":"To establish or decide.","c":"決定；確定","s":"The final exam will determine your grade.","t":"期末考將決定你的成績。","src":"386"},{"w":"deviate","p":"v.","d":"To move away from a set path or norm.","c":"偏離","s":"When the new evidence was uncovered the lawyer deviated from the original plan.","t":"新證據被發現後，律師偏離了原本的計畫。","src":"386"},{"w":"devise","p":"v.","d":"To come up with (a plan).","c":"設計；想出","s":"Lana devised a plan to make herself famous.","t":"拉娜想出一個讓自己出名的計畫。","src":"386"}]},{"unit":9,"theme":"diligent – distinct","cards":[{"w":"diligent","p":"adj.","d":"Showing care and effort in one’s work or duties.","c":"勤勉的；勤奮的","s":"She is diligent in completing her assignments on time.","t":"她勤奮地準時完成作業。","src":"306"},{"w":"diminish","p":"v.","d":"To decrease in size or importance.","c":"減少；削弱","s":"The politician's influence has diminished over time.","t":"那位政治人物的影響力隨著時間減弱了。","src":"386"},{"w":"directed","p":"adj.","d":"Managed or guided.","c":"執導的；指導的","s":"This new film was directed by a renowned artist.","t":"這部新電影是由一位知名藝術家執導的。","src":"386"},{"w":"disagreement","p":"n.","d":"A difference of opinion.","c":"意見分歧","s":"An intense disagreement arose over the contract terms.","t":"合約條款引發了激烈的意見分歧。","src":"386"},{"w":"disastrous","p":"adj.","d":"Causing great harm or failure.","c":"災難性的","s":"The earthquake had disastrous consequences for the island.","t":"這場地震對該島造成了災難性的後果。","src":"386"},{"w":"discern","p":"v.","d":"To recognize or perceive something clearly, especially with effort.","c":"辨別；識別","s":"She could easily discern the subtle differences between the two paintings.","t":"她能輕易分辨出兩幅畫之間細微的差異。","src":"306"},{"w":"disconcerting","p":"adj.","d":"Causing discomfort or confusion; unsettling.","c":"令人不安的","s":"The sudden change in schedule was disconcerting to everyone involved.","t":"行程突然改變讓所有相關的人都感到不安。","src":"306 + 386"},{"w":"discord","p":"n.","d":"Disagreement.","c":"不和；紛爭","s":"Disputes over money caused intense discord in the family.","t":"金錢糾紛在家中造成了激烈的不和。","src":"386"},{"w":"discount","p":"v.","d":"To disregard or reduce in value.","c":"忽視；打折","s":"The teacher discounted his students' concerns.","t":"老師不把學生的擔憂當一回事。","src":"386"},{"w":"discourage","p":"v.","d":"To dissuade or deter.","c":"使氣餒；勸阻","s":"Luna tried to discourage her brother from moving out of the house.","t":"露娜試著勸阻弟弟不要搬出家裡。","src":"386"},{"w":"discreet","p":"adj.","d":"Careful in one’s speech or actions to avoid causing offense or revealing private information.","c":"謹慎的；言行慎重的","s":"They held a discreet meeting to discuss the confidential matter.","t":"他們舉行了一場低調的會議，討論機密事項。","src":"306"},{"w":"discretion","p":"n.","d":"The ability to make responsible choices.","c":"謹慎；判斷力","s":"The detective handled the matter with great discretion.","t":"警探非常謹慎地處理這件事。","src":"386"},{"w":"disengage","p":"v.","d":"To separate or detach something from a connection or attachment.","c":"使脫離；使分離","s":"He tried to disengage himself from the argument but couldn’t resist.","t":"他試著讓自己脫離這場爭吵，卻還是忍不住插嘴。","src":"306 + 386"},{"w":"dismiss","p":"v.","d":"To reject or send away.","c":"駁回；解散","s":"The teacher dismissed the idea to end class early.","t":"老師否決了提早下課的提議。","src":"386"},{"w":"dismissive","p":"adj.","d":"Showing disregard or lack of interest; treating something as unworthy of attention.","c":"輕蔑的；不屑一顧的","s":"Her dismissive attitude towards the suggestions irritated the group.","t":"她對這些建議不屑一顧的態度惹惱了大家。","src":"306"},{"w":"disorienting","p":"adj.","d":"Causing confusion or loss of direction, especially in space or time.","c":"使人迷失方向的；令人困惑的","s":"The sudden change in environment was disorienting, leaving everyone uncertain.","t":"環境的突然改變令人迷失方向，讓每個人都無所適從。","src":"306 + 386"},{"w":"disparage","p":"v.","d":"To belittle or speak negatively about.","c":"貶低；詆毀","s":"The politician disparaged his opponent's ideas on tax cuts.","t":"那位政治人物貶低對手的減稅主張。","src":"386"},{"w":"disparate","p":"adj.","d":"Essentially different or dissimilar in kind or quality.","c":"迥然不同的；無法比較的","s":"The two teams were made up of disparate groups with very different backgrounds.","t":"這兩支隊伍由背景截然不同的群體組成。","src":"306 + 386"},{"w":"dispute","p":"v./n.","d":"To argue about something; a disagreement or conflict.","c":"爭論；爭執","s":"They had a heated dispute over the project’s direction.","t":"他們對計畫的方向發生了激烈的爭論。","src":"306 + 386"},{"w":"distinct","p":"adj.","d":"Clearly different or separate.","c":"截然不同的；獨特的","s":"My twin sons have distinct personalities.","t":"我的雙胞胎兒子個性截然不同。","src":"386"}]},{"unit":10,"theme":"distract – engaging","cards":[{"w":"distract","p":"v.","d":"To divert attention.","c":"使分心","s":"The rattling noise distracted Javi from his work.","t":"喀啦喀啦的聲音讓哈維無法專心工作。","src":"386"},{"w":"distressed","p":"adj.","d":"Suffering from anxiety or pain.","c":"苦惱的；憂傷的","s":"The woman looked distressed after the doctor's call.","t":"接到醫生的電話後，那名女子看起來很苦惱。","src":"386"},{"w":"diverge","p":"v.","d":"To separate or move in different directions from a common point.","c":"分歧；分岔","s":"The two paths diverge at the foot of the mountain, leading to different destinations.","t":"兩條小路在山腳下分岔，通往不同的目的地。","src":"306 + 386"},{"w":"diverse","p":"adj.","d":"Showing a great deal of variety; very different from one another.","c":"多樣的；各異的","s":"The class was made up of a diverse group of students from various cultural backgrounds.","t":"這個班級由來自各種文化背景、多元的學生組成。","src":"306 + 386"},{"w":"docile","p":"adj.","d":"Ready to accept control or instruction; submissive.","c":"溫馴的；順從的","s":"The dog was surprisingly docile despite its large size.","t":"儘管體型很大，那隻狗卻出奇地溫順。","src":"306"},{"w":"domesticate","p":"v.","d":"To tame or train an animal or plant to live and reproduce in a human-controlled environment.","c":"馴養；馴化","s":"They worked for years to domesticate the wild horses.","t":"他們花了好幾年馴化那些野馬。","src":"306"},{"w":"dominance","p":"n.","d":"The state of being in control or superior.","c":"支配地位；優勢","s":"The company's dominance in the market is evident.","t":"這家公司在市場上的主導地位顯而易見。","src":"386"},{"w":"dormant","p":"adj.","d":"Inactive but capable of becoming active.","c":"休眠的；靜止的","s":"The volcano beneath Mount Fuji has been dormant for centuries.","t":"富士山底下的火山已經休眠了好幾個世紀。","src":"386"},{"w":"dynamic","p":"adj.","d":"Constantly changing or energetic.","c":"充滿活力的；動態的；不斷變化的","s":"My coworker is a dynamic speaker who commands attention wherever she goes.","t":"我的同事是個充滿活力的演講者，走到哪裡都能吸引目光。","src":"386"},{"w":"earnest","p":"adj.","d":"Serious and sincere.","c":"誠摯的；認真的","s":"He felt terrible about breaking the mirror and made an earnest apology.","t":"他對打破鏡子感到很過意不去，誠懇地道了歉。","src":"386"},{"w":"eclipse","p":"v.","d":"To overshadow or surpass.","c":"使黯然失色；掩蓋","s":"The headliner's performance eclipsed all others in the concert.","t":"壓軸歌手的表演讓這場演唱會的其他表演都黯然失色。","src":"386"},{"w":"elaborate","p":"v./adj.","d":"To develop or present something in great detail; involving many careful parts.","c":"詳細闡述；精心製作的","s":"She elaborated on her idea during the meeting, providing several examples.","t":"她在會議中詳細闡述了自己的想法，並舉了幾個例子。","src":"306"},{"w":"eloquent","p":"adj.","d":"Fluent or persuasive in speaking or writing.","c":"雄辯的；口才流利的","s":"The speaker’s eloquent words inspired the audience.","t":"演講者雄辯的話語激勵了聽眾。","src":"306 + 386"},{"w":"elusive","p":"adj.","d":"Difficult to find, catch, or achieve; hard to define or understand.","c":"難以捉摸的；難以獲得的","s":"The solution to the puzzle was elusive, and no one could solve it.","t":"這道謎題的答案難以捉摸，沒有人解得出來。","src":"306 + 386"},{"w":"emphasize","p":"v.","d":"To give special importance or attention to something.","c":"強調","s":"The teacher emphasized the importance of completing the assignment on time.","t":"老師強調準時完成作業的重要性。","src":"306"},{"w":"encompass","p":"v.","d":"To include or surround.","c":"包含；涵蓋","s":"The project encompasses multiple disciplines.","t":"這項計畫涵蓋多個學科。","src":"386"},{"w":"encounter","p":"v.","d":"To meet or face unexpectedly.","c":"邂逅；遭遇","s":"She encountered an old friend at the store.","t":"她在商店裡遇到了一位老朋友。","src":"386"},{"w":"encourage","p":"v.","d":"To support or inspire.","c":"鼓勵","s":"Teachers often encourage students to ask questions.","t":"老師經常鼓勵學生發問。","src":"386"},{"w":"enduring","p":"adj.","d":"Lasting over time.","c":"持久的；歷久不衰的","s":"Their 50-year friendship is enduring.","t":"他們五十年的友誼歷久不衰。","src":"386"},{"w":"engaging","p":"adj.","d":"Attractive or charming; capable of holding one’s attention.","c":"引人入勝的；有魅力的","s":"The speaker delivered an engaging presentation that kept the audience captivated.","t":"演講者做了一場引人入勝的報告，讓聽眾聽得入迷。","src":"306"}]},{"unit":11,"theme":"enhance – fallacious","cards":[{"w":"enhance","p":"v.","d":"To improve the quality or value of something.","c":"提高；增強；改善","s":"The bright lighting enhanced the appearance of the room.","t":"明亮的燈光讓房間看起來更好看。","src":"306"},{"w":"ephemeral","p":"adj.","d":"Lasting for a very short time.","c":"短暫的；朝生暮死的","s":"The beauty of the sunset was ephemeral but breathtaking.","t":"夕陽的美短暫卻令人屏息。","src":"306"},{"w":"evidence","p":"n.","d":"Information that supports a conclusion.","c":"證據","s":"There is strong evidence to support the theory.","t":"有強而有力的證據支持這個理論。","src":"386"},{"w":"evoke","p":"v.","d":"To draw forth or call up.","c":"喚起；引起","s":"Horror movies are great at evoking fear.","t":"恐怖片很擅長喚起恐懼。","src":"386"},{"w":"exacerbate","p":"v.","d":"To make a problem worse.","c":"惡化；激怒","s":"His rude comments only exacerbated the tense situation.","t":"他無禮的言論只讓緊張的情勢更加惡化。","src":"386"},{"w":"exactitude","p":"n.","d":"The quality of being precise or accurate.","c":"精確性","s":"The scientist's exactitude ensured reliable results.","t":"這位科學家的精確確保了可靠的結果。","src":"386"},{"w":"exaggerate","p":"v.","d":"To overstate or magnify beyond the truth.","c":"誇大","s":"My cousin tends to exaggerate his achievements.","t":"我的表哥常常誇大自己的成就。","src":"386"},{"w":"exceed","p":"v.","d":"To go beyond a limit.","c":"超過；超越","s":"The driver exceeded the speed limit by nearly 30 miles an hour.","t":"那名駕駛超速將近每小時三十英里。","src":"386"},{"w":"exemplify","p":"v.","d":"To illustrate or clarify by giving an example.","c":"舉例說明；是...的典範","s":"The teacher used the novel to exemplify the themes of love and sacrifice.","t":"老師用這本小說來例示愛與犧牲的主題。","src":"306 + 386"},{"w":"exhaustive","p":"adj.","d":"Thorough and complete.","c":"詳盡的；徹底的","s":"The 300-page report provided an exhaustive analysis.","t":"這份三百頁的報告提供了詳盡的分析。","src":"386"},{"w":"expansion","p":"n.","d":"The act of increasing in size or scope.","c":"擴張；擴展","s":"The company's expansion into international markets has been successful so far.","t":"這家公司拓展到國際市場的擴張到目前為止很成功。","src":"386"},{"w":"expensive","p":"adj.","d":"Costing a lot of money.","c":"昂貴的","s":"My sister's diamond ring was extremely expensive.","t":"我姊姊的鑽戒非常昂貴。","src":"386"},{"w":"experiment","p":"n.","d":"A test to discover something new.","c":"實驗","s":"The scientist conducted an experiment to test the theory.","t":"科學家進行了一項實驗來驗證這個理論。","src":"386"},{"w":"explicable","p":"adj.","d":"Able to be explained.","c":"可解釋的","s":"Once I knew the full story, my boyfriend's actions were explicable given the circumstances.","t":"一旦我知道了來龍去脈，男友在那種情況下的行為就可以解釋了。","src":"386"},{"w":"exploit","p":"v.","d":"To take advantage of something unfairly.","c":"開發；剝削","s":"The mining company was accused of exploiting workers.","t":"那家礦業公司被指控剝削工人。","src":"386"},{"w":"extensive","p":"adj.","d":"Covering a large area or scope.","c":"廣泛的","s":"The Art Institute of Chicago has an extensive Impressionist collection.","t":"芝加哥藝術博物館擁有大量的印象派收藏。","src":"386"},{"w":"extraneous","p":"adj.","d":"Unrelated or unnecessary.","c":"無關的；外來的","s":"The report contained too much extraneous information that didn't matter to the trial.","t":"這份報告包含太多與審判無關的多餘資訊。","src":"386"},{"w":"fabricate","p":"v.","d":"To invent or make something; to invent or concoct something, usually with the intention to deceive.","c":"捏造；製造","s":"He fabricated the story to cover up his mistake.","t":"他捏造了這個故事來掩飾自己的錯誤。","src":"306 + 386"},{"w":"facetious","p":"adj.","d":"Treating serious issues with deliberately inappropriate humor.","c":"愛開玩笑的；不正經的","s":"His facetious comments during the meeting were not appreciated.","t":"他在會議中開玩笑的言論並不受歡迎。","src":"306"},{"w":"fallacious","p":"adj.","d":"Based on a mistaken belief or unsound reasoning.","c":"謬誤的；欺騙性的","s":"His argument was fallacious and lacked logical support.","t":"他的論點是錯誤的，缺乏邏輯支持。","src":"306"}]},{"unit":12,"theme":"fathom – habitual","cards":[{"w":"fathom","p":"v.","d":"To understand or comprehend something deeply.","c":"理解；領悟","s":"It’s hard to fathom the scale of the universe.","t":"宇宙的規模令人難以理解。","src":"306"},{"w":"favorable","p":"adj.","d":"Showing approval or support; likely to lead to success or good results.","c":"有利的；贊同的","s":"The weather conditions were favorable for the outdoor event.","t":"天氣條件很適合舉辦這場戶外活動。","src":"306"},{"w":"fervent","p":"adj.","d":"Displaying passionate intensity.","c":"熱切的；熱誠的","s":"Her fervent dedication to the cause was evident in her work.","t":"她對這項理想的熱忱投入在她的工作中顯而易見。","src":"306"},{"w":"flamboyant","p":"adj.","d":"Tending to attract attention because of exuberance, confidence, or stylishness.","c":"艷麗的；炫耀的","s":"He wore a flamboyant outfit to the party, drawing all eyes to him.","t":"他穿了一套華麗搶眼的服裝去參加派對，吸引了所有人的目光。","src":"306"},{"w":"fluctuate","p":"v.","d":"To vary or change frequently, often in an irregular or unpredictable way.","c":"波動；起伏","s":"The stock prices fluctuate constantly, making it difficult to predict trends.","t":"股價不斷波動，讓人很難預測趨勢。","src":"306"},{"w":"foretell","p":"v.","d":"To predict or estimate something that will happen in the future.","c":"預言；預示","s":"The fortune teller tried to foretell the future based on the cards.","t":"算命師試著根據紙牌預言未來。","src":"306 + 386"},{"w":"forge","p":"v.","d":"To create or form something through effort or through heating and shaping, especially metal.","c":"鍛造；締造","s":"The blacksmith forged a new sword from the hot iron.","t":"鐵匠用燒熱的鐵鍛造了一把新劍。","src":"306"},{"w":"fortuitous","p":"adj.","d":"Happening by chance or accident.","c":"偶然的；幸運的","s":"It was a fortuitous encounter that led to their collaboration.","t":"那是一次幸運的偶遇，促成了他們的合作。","src":"306"},{"w":"foster","p":"v.","d":"To encourage or promote development.","c":"培養；促進","s":"Teachers should strive to foster creativity in students.","t":"老師應努力培養學生的創造力。","src":"386"},{"w":"fragile","p":"adj.","d":"Easily broken or delicate.","c":"脆弱的；易碎的","s":"The glass vase is very fragile.","t":"這只玻璃花瓶非常易碎。","src":"386"},{"w":"fruitless","p":"adj.","d":"Failing to achieve desired results.","c":"徒勞的；無結果的","s":"Their search for survivors was fruitless.","t":"他們搜尋生還者的行動毫無結果。","src":"386"},{"w":"gallant","p":"adj.","d":"Brave, heroic, or exceptionally polite and attentive.","c":"英勇的；殷勤的","s":"The gallant knight ventured into the dangerous forest.","t":"英勇的騎士冒險進入危險的森林。","src":"306"},{"w":"garner","p":"v.","d":"To collect or gather, especially information or approval.","c":"蒐集；獲得","s":"The candidate garnered widespread support through her speeches.","t":"這位候選人透過演講獲得了廣泛的支持。","src":"306"},{"w":"genuine","p":"adj.","d":"Authentic or real.","c":"真誠的；真正的","s":"His apology seemed genuine.","t":"他的道歉似乎是真誠的。","src":"386"},{"w":"glaring","p":"adj.","d":"Extremely obvious or conspicuous.","c":"顯而易見的；刺眼的","s":"The glaring mistake on the report was impossible to overlook.","t":"報告上那個明顯的錯誤不可能被忽視。","src":"306"},{"w":"glorify","p":"v.","d":"To praise or honor highly.","c":"讚揚；美化","s":"The team was glorified for their historic championship win.","t":"這支球隊因贏得歷史性的冠軍而備受頌揚。","src":"306"},{"w":"grapple","p":"v.","d":"To struggle or wrestle with something.","c":"搏鬥；努力應付","s":"The country is grappling with economic issues.","t":"這個國家正在努力應付經濟問題。","src":"386"},{"w":"gregarious","p":"adj.","d":"Fond of company; sociable.","c":"群居的；社交的","s":"Her gregarious personality made her the life of the party.","t":"她愛交際的個性讓她成為派對的靈魂人物。","src":"306"},{"w":"gullible","p":"adj.","d":"Easily deceived or tricked.","c":"易受騙的；輕信的","s":"The gullible tourist fell for the vendor's overpriced trinkets.","t":"那名容易受騙的觀光客上了小販的當，買了貴得離譜的小飾品。","src":"306"},{"w":"habitual","p":"adj.","d":"Done regularly or repeatedly.","c":"習慣性的","s":"His habitual lateness annoyed his coworkers.","t":"他習慣性的遲到惹惱了同事。","src":"386"}]},{"unit":13,"theme":"haphazard – imminent","cards":[{"w":"haphazard","p":"adj.","d":"Lacking organization or planning.","c":"雜亂無章的；隨意的","s":"The project was completed in a haphazard manner.","t":"這個計畫是以雜亂無章的方式完成的。","src":"386"},{"w":"hasten","p":"v.","d":"To move or act quickly.","c":"加速；趕緊","s":"He hastened to finish his homework before the deadline.","t":"他趕緊在截止期限前完成作業。","src":"306"},{"w":"haughty","p":"adj.","d":"Arrogantly superior and disdainful.","c":"高傲的；傲慢的","s":"The celebrity's haughty demeanor alienated her fans.","t":"那位名人傲慢的態度讓粉絲疏遠了她。","src":"306"},{"w":"heed","p":"v.","d":"To pay attention to or take notice of.","c":"注意；聽從","s":"The teacher warned them to heed the instructions carefully.","t":"老師警告他們要仔細留意指示。","src":"306"},{"w":"hibernate","p":"v.","d":"To spend a long period of time in a dormant or inactive state, especially during the winter.","c":"冬眠","s":"Bears hibernate during the winter to conserve energy.","t":"熊在冬天冬眠以保存能量。","src":"306"},{"w":"hibernation","p":"n.","d":"A state of dormancy or deep sleep.","c":"冬眠(狀態)","s":"Many bear species go into hibernation during the winter.","t":"許多種類的熊在冬天會進入冬眠。","src":"386"},{"w":"highlight","p":"v.","d":"To emphasize or make noticeable.","c":"強調；凸顯","s":"The article highlights key points of the debate.","t":"這篇文章強調了這場辯論的重點。","src":"386"},{"w":"hinder","p":"v.","d":"To obstruct or slow progress.","c":"阻礙","s":"The heavy traffic hindered our journey.","t":"繁忙的交通阻礙了我們的行程。","src":"386"},{"w":"hoard","p":"v.","d":"To accumulate and hide or store away.","c":"囤積；貯藏","s":"He hoarded supplies for months, preparing for a potential shortage.","t":"他囤積物資好幾個月，為可能的短缺做準備。","src":"306 + 386"},{"w":"homogeneous","p":"adj.","d":"Of the same kind; alike.","c":"同質的；均勻的","s":"The committee was surprisingly homogeneous in their views on the matter.","t":"委員會對這件事的看法出奇地一致。","src":"306 + 386"},{"w":"humble","p":"adj.","d":"Modest or low estimate of one’s importance.","c":"謙遜的","s":"Despite his success, he remained humble and approachable.","t":"儘管功成名就，他依然謙虛又平易近人。","src":"306"},{"w":"hypothesize","p":"v.","d":"To form a theory or assumption.","c":"假設；推測","s":"Scientists hypothesize about the origin of the universe.","t":"科學家對宇宙的起源提出假設。","src":"386"},{"w":"hypothetical","p":"adj.","d":"Based on an assumption or theory.","c":"假設的；虛擬的","s":"The scientist presented a hypothetical scenario to explain the phenomenon.","t":"科學家提出一個假設的情境來解釋這個現象。","src":"306"},{"w":"illogical","p":"adj.","d":"Lacking sense or clear, sound reasoning.","c":"不合邏輯的","s":"His argument was illogical and did not convince the audience.","t":"他的論點不合邏輯，沒能說服聽眾。","src":"306"},{"w":"illuminate","p":"v.","d":"To light up or clarify.","c":"照亮；闡明","s":"The lantern illuminated the path through the forest.","t":"燈籠照亮了穿過森林的小徑。","src":"306"},{"w":"illustrious","p":"adj.","d":"Well-known, respected, and admired for achievements.","c":"卓越的；著名的","s":"Her illustrious career as a scientist inspired countless students.","t":"她身為科學家的傑出生涯啟發了無數學生。","src":"306"},{"w":"imaginative","p":"adj.","d":"Creative and full of new ideas.","c":"富有想像力的","s":"The artist's work is highly imaginative.","t":"這位藝術家的作品極富想像力。","src":"386"},{"w":"imitation","p":"n.","d":"A copy or replica of something.","c":"模仿；仿製品","s":"The purse was an imitation of a designer brand.","t":"那個包包是名牌的仿冒品。","src":"386"},{"w":"immaculate","p":"adj.","d":"Perfectly clean or free from flaws.","c":"一塵不染的；完美無瑕的","s":"The house was immaculate after the cleaning crew left.","t":"清潔人員離開後，房子一塵不染。","src":"306"},{"w":"imminent","p":"adj.","d":"About to happen; impending.","c":"迫近的；即將發生的","s":"The storm's arrival was imminent, so we quickly took shelter.","t":"暴風雨即將來臨，所以我們趕緊找地方躲避。","src":"306 + 386"}]},{"unit":14,"theme":"immune – inadvertently","cards":[{"w":"immune","p":"adj.","d":"Resistant to disease or harm.","c":"免疫的；不受影響的","s":"He's immune to the virus due to vaccination.","t":"因為打過疫苗，他對這種病毒免疫。","src":"386"},{"w":"impart","p":"v.","d":"To make information known or to give something.","c":"傳授；賦予","s":"The professor imparted her vast knowledge to the eager students.","t":"教授把她淵博的知識傳授給求知若渴的學生。","src":"306"},{"w":"impartial","p":"adj.","d":"Not biased or prejudiced; treating all sides equally.","c":"公正的；不偏不倚的","s":"The judge was impartial, ensuring a fair trial for both parties.","t":"法官態度公正，確保雙方都能得到公平的審判。","src":"306 + 386"},{"w":"impede","p":"v.","d":"To hinder or obstruct the progress of.","c":"阻礙；妨礙","s":"Heavy traffic impeded the emergency vehicle’s progress.","t":"繁忙的交通阻礙了救護車前進。","src":"306"},{"w":"impending","p":"adj.","d":"Approaching or about to happen.","c":"即將發生的；迫近的","s":"They prepared for the impending storm by boarding up windows.","t":"他們把窗戶釘上木板，為即將來臨的暴風雨做準備。","src":"386"},{"w":"impenetrable","p":"adj.","d":"Impossible to pass through.","c":"無法穿透的","s":"The fortress was impenetrable to enemy attack.","t":"那座堡壘是敵人攻不破的。","src":"386"},{"w":"imperceptible","p":"adj.","d":"Impossible to perceive or detect; so slight that it cannot be noticed.","c":"難以察覺的；極細微的","s":"The change in temperature was so imperceptible that no one noticed it.","t":"溫度的變化細微到難以察覺，所以沒有人注意到。","src":"306 + 386"},{"w":"impervious","p":"adj.","d":"Not affected or influenced by something.","c":"不受影響的；不透水的","s":"The material is impervious to water, making it ideal for roofing.","t":"這種材料不透水，很適合用來做屋頂。","src":"306"},{"w":"impetuous","p":"adj.","d":"Acting or done quickly without thought or care.","c":"衝動的；魯莽的","s":"Her impetuous decision to quit her job shocked her colleagues.","t":"她衝動地決定辭職，讓同事們大吃一驚。","src":"306"},{"w":"implement","p":"v.","d":"To put a plan or decision into action; to carry out.","c":"實施；執行","s":"The company decided to implement the new policy starting next month.","t":"公司決定從下個月開始實施新政策。","src":"306 + 386"},{"w":"implication","p":"n.","d":"A possible consequence or meaning.","c":"含意；影響","s":"The policy change has serious implications for lobbyists.","t":"這項政策變動對遊說人士有重大的影響。","src":"386"},{"w":"implicit","p":"adj.","d":"Implied rather than stated directly.","c":"含蓄的；暗示的","s":"His approval was implicit in his silence.","t":"他的沉默中暗含著認可。","src":"386"},{"w":"implore","p":"v.","d":"To beg earnestly or desperately.","c":"懇求；哀求；乞求","s":"The student implored the teacher for an extension on the project.","t":"那名學生懇求老師延長專題的繳交期限。","src":"306"},{"w":"impractical","p":"adj.","d":"Not sensible or realistic; not suited to the situation or purpose.","c":"不切實際的","s":"The plan was deemed impractical due to its high cost and complexity.","t":"由於成本高又複雜，這個計畫被認為不切實際。","src":"306 + 386"},{"w":"improvise","p":"v.","d":"To create or perform something without preparation or planning, often with available materials.","c":"即興創作；臨場發揮","s":"The actor had to improvise his lines when the script was lost.","t":"劇本遺失後，那位演員只好即興說台詞。","src":"306 + 386"},{"w":"imprudent","p":"adj.","d":"Not showing care for the consequences of an action.","c":"輕率的；不明智的","s":"It was imprudent of him to invest all his savings in one risky venture.","t":"他把所有積蓄都投資在一項高風險的事業上，實在很不明智。","src":"306"},{"w":"inactive","p":"adj.","d":"Not engaged in movement or activity.","c":"不活躍的；靜止的","s":"The volcano has been inactive for decades.","t":"這座火山已經好幾十年沒有活動了。","src":"386"},{"w":"inadequate","p":"adj.","d":"Not sufficient or suitable for the intended purpose; lacking in quality or quantity.","c":"不足的；不適當的","s":"The equipment provided was inadequate for the job, resulting in delays.","t":"提供的設備不足以完成這項工作，因而造成延誤。","src":"306 + 386"},{"w":"inadvertent","p":"adj.","d":"Occurring by chance or without intention; unintentional.","c":"無意的；非故意的","s":"The inadvertent mistake caused the project deadline to be missed.","t":"這個無心的錯誤導致專案錯過了截止期限。","src":"306"},{"w":"inadvertently","p":"adv.","d":"Unintentionally or by accident.","c":"無意間；不小心地","s":"The new worker caused a ruckus when he inadvertently deleted an important file.","t":"那名新員工不小心刪除了一個重要檔案，引起一陣騷動。","src":"386"}]},{"unit":15,"theme":"incessant – innocuous","cards":[{"w":"incessant","p":"adj.","d":"Continuing without pause or interruption.","c":"不停的；持續不斷的","s":"The incessant noise of the construction work made it hard to focus.","t":"施工持續不斷的噪音讓人難以專心。","src":"306"},{"w":"incite","p":"v.","d":"To encourage or stir up (violent or unlawful behavior).","c":"煽動；激起","s":"His speech incited anger among the protesters.","t":"他的演講激起了抗議者的憤怒。","src":"306 + 386"},{"w":"inconclusive","p":"adj.","d":"Not leading to a clear or definite conclusion; ambiguous.","c":"不確定的；未有定論的","s":"The results of the experiment were inconclusive, so further testing was needed.","t":"實驗結果並無定論，所以需要進一步測試。","src":"306"},{"w":"inconspicuous","p":"adj.","d":"Not being easily seen or noticed.","c":"不顯眼的；不引人注意的","s":"The spy was inconspicuous as he moved through the crowd.","t":"那名間諜穿過人群時毫不起眼。","src":"386"},{"w":"indecipherable","p":"adj.","d":"Impossible to read, interpret, or understand due to lack of clarity or complexity.","c":"難以辨認的；無法解讀的","s":"The handwriting was so messy it was completely indecipherable.","t":"字跡潦草到完全無法辨認。","src":"306 + 386"},{"w":"indicate","p":"v.","d":"To point out or show.","c":"指出；顯示","s":"The results indicate a positive trend.","t":"結果顯示出正向的趨勢。","src":"386"},{"w":"indifference","p":"n.","d":"Lack of interest or concern.","c":"漠不關心","s":"Natalia's indifference to the situation frustrated her sisters.","t":"娜塔莉亞對這個情況漠不關心，讓她的姊妹們很沮喪。","src":"386"},{"w":"indisputable","p":"adj.","d":"Unable to be challenged or denied.","c":"無可爭議的","s":"Because the evidence was indisputable, the lawyer was certain his client would go free.","t":"由於證據無可爭辯，律師確信他的當事人會獲釋。","src":"386"},{"w":"indistinct","p":"adj.","d":"Not clear or sharply defined.","c":"模糊不清的","s":"The figure in the distance was blurry and indistinct.","t":"遠處的身影模糊不清。","src":"386"},{"w":"indulge","p":"v.","d":"To allow oneself to enjoy.","c":"縱容；沉溺","s":"After a long day of work, Jane decided to indulge in a piece of cake.","t":"辛苦工作了一整天後，珍決定犒賞自己一塊蛋糕。","src":"386"},{"w":"ineffectual","p":"adj.","d":"Not producing the desired effect.","c":"無效的；軟弱無能的","s":"The mayor's efforts to change the city's parking rules were ineffectual.","t":"市長改變市內停車規定的努力沒有成效。","src":"386"},{"w":"inept","p":"adj.","d":"Having or showing no skill; clumsy.","c":"笨拙的；不稱職的","s":"His inept handling of the situation only made things worse.","t":"他笨拙地處理這個情況，只讓事情變得更糟。","src":"306"},{"w":"inevitable","p":"adj.","d":"Certain to happen; unavoidable.","c":"不可避免的","s":"Failure seemed inevitable given the lack of preparation.","t":"由於缺乏準備，失敗似乎是無法避免的。","src":"306 + 386"},{"w":"inexpensive","p":"adj.","d":"Not costly.","c":"不昂貴的；便宜的","s":"The new Vietnamese restaurant down the street serves inexpensive but delicious meals.","t":"街上那家新開的越南餐廳供應便宜又美味的餐點。","src":"386"},{"w":"inexplicable","p":"adj.","d":"Unable to be explained or understood; baffling.","c":"無法解釋的","s":"The disappearance of the airplane remains inexplicable, despite extensive research.","t":"儘管經過大規模調查，那架飛機的失蹤仍然無法解釋。","src":"306 + 386"},{"w":"infallible","p":"adj.","d":"Incapable of making mistakes or being wrong; flawless.","c":"絕對正確的","s":"The scientist believed the theory to be infallible, but later it was disproven.","t":"這位科學家相信這個理論絕對正確，但後來它被推翻了。","src":"306"},{"w":"influence","p":"n.","d":"The power to affect others.","c":"影響力","s":"The pastor's speech had a strong influence on the audience.","t":"牧師的講道對聽眾有強大的影響。","src":"386"},{"w":"infrequent","p":"adj.","d":"Not occurring often.","c":"罕見的；不常發生的","s":"Rain is infrequent in the Atacama Desert.","t":"阿塔卡馬沙漠很少下雨。","src":"386"},{"w":"inhibit","p":"v.","d":"To hinder or restrain.","c":"抑制；阻礙","s":"Fear of failure can inhibit creativity.","t":"對失敗的恐懼會抑制創造力。","src":"386"},{"w":"innocuous","p":"adj.","d":"Harmless or not likely to offend or cause injury.","c":"無害的","s":"The remark was innocuous and didn't offend anyone.","t":"那句話無傷大雅，沒有冒犯到任何人。","src":"306 + 386"}]},{"unit":16,"theme":"innovative – involuntarily","cards":[{"w":"innovative","p":"adj.","d":"Introducing or using new methods, ideas, or products; original and creative.","c":"創新的","s":"The startup was praised for its innovative approach to solving the problem.","t":"這家新創公司因其解決問題的創新方法而受到讚揚。","src":"306"},{"w":"insensible","p":"adj.","d":"Unaware or indifferent.","c":"無知覺的；麻木的","s":"The father was insensible to his children's boredom.","t":"那位父親沒有察覺到孩子們的無聊。","src":"386"},{"w":"insignificant","p":"adj.","d":"Too small or unimportant to matter.","c":"微不足道的","s":"The difference in price between the two ice creams was insignificant.","t":"兩種冰淇淋的價差微不足道。","src":"386"},{"w":"inspect","p":"v.","d":"To examine closely.","c":"檢查","s":"The contractor will inspect the building for safety.","t":"承包商將檢查這棟建築物的安全。","src":"386"},{"w":"inspirational","p":"adj.","d":"Providing motivation or encouragement.","c":"激勵人心的","s":"Evan's story of recovering from a severe car accident was inspirational to many.","t":"艾文從嚴重車禍中康復的故事激勵了許多人。","src":"386"},{"w":"intangible","p":"adj.","d":"Not able to be touched or measured.","c":"無形的","s":"Love is an intangible concept.","t":"愛是一種無形的概念。","src":"386"},{"w":"intentional","p":"adj.","d":"Done on purpose.","c":"故意的","s":"By reading the evidence, I could tell the man's actions were intentional.","t":"從證據來看，我可以斷定那名男子的行為是故意的。","src":"386"},{"w":"interchangeable","p":"adj.","d":"Able to be exchanged or replaced with another item without significant difference.","c":"可互換的","s":"The two parts were interchangeable, making repairs easier.","t":"這兩個零件可以互換，讓維修更容易。","src":"306 + 386"},{"w":"interject","p":"v.","d":"To say something abruptly, especially during a conversation.","c":"插嘴；打斷","s":"He interjected a quick comment during the heated discussion.","t":"他在激烈的討論中插了一句簡短的評論。","src":"306 + 386"},{"w":"interpret","p":"v.","d":"To explain the meaning of something.","c":"解釋；詮釋","s":"I don't understand this poem; can you interpret it for met?","t":"我看不懂這首詩，你可以幫我解釋嗎？","src":"386"},{"w":"intersect","p":"v.","d":"To cross or meet at a point.","c":"相交；交叉","s":"The two streets intersect downtown.","t":"這兩條街在市中心交會。","src":"386"},{"w":"intrepid","p":"adj.","d":"Fearless, adventurous.","c":"無畏的；勇敢的","s":"The intrepid explorers ventured into uncharted territory.","t":"無畏的探險家們冒險進入未知的領域。","src":"306"},{"w":"intricate","p":"adj.","d":"Very detailed or complex; complicated in design or structure.","c":"錯綜複雜的；精細的","s":"The intricate pattern on the fabric was carefully designed.","t":"布料上錯綜複雜的圖案是精心設計的。","src":"306 + 386"},{"w":"intriguing","p":"adj.","d":"Arousing curiosity or interest.","c":"引人入勝的；耐人尋味的","s":"The mystery novel was intriguing because I couldn't figure out who the murderer was.","t":"這本推理小說很引人入勝，因為我猜不出兇手是誰。","src":"386"},{"w":"invalidate","p":"v.","d":"To make something invalid or void; to render something without legal or logical value.","c":"使無效；使作廢","s":"The evidence presented in court was enough to invalidate his claim.","t":"法庭上提出的證據足以使他的主張無效。","src":"306 + 386"},{"w":"invasive","p":"adj.","d":"Tending to intrude on or interfere with something, often in an unwelcome or harmful way.","c":"侵入性的","s":"The invasive species spread quickly and threatened the local ecosystem.","t":"這種入侵物種迅速擴散，威脅到當地的生態系。","src":"306"},{"w":"invent","p":"v.","d":"To create something new.","c":"發明","s":"Thomas Edison invented the incandescent light bulb.","t":"愛迪生發明了白熾燈泡。","src":"386"},{"w":"inventive","p":"adj.","d":"Having the ability to create new things or ideas; creative and original.","c":"有創造力的；善於創新的","s":"The inventive designer introduced new ideas that transformed the industry.","t":"這位富有創意的設計師引進了改變整個產業的新點子。","src":"306"},{"w":"investigation","p":"n.","d":"Systematic inquiries to uncover facts.","c":"調查","s":"The police conducted a thorough investigation of the crime scene.","t":"警方對犯罪現場進行了徹底的調查。","src":"386"},{"w":"involuntarily","p":"adv.","d":"Done without conscious control.","c":"不由自主地","s":"She involuntarily gasped in surprise.","t":"她不由自主地驚訝倒抽一口氣。","src":"386"}]},{"unit":17,"theme":"iridescent – magnanimous","cards":[{"w":"iridescent","p":"adj.","d":"Showing luminous colors that seem to change when seen from different angles.","c":"色彩斑斕的；五彩的","s":"The soap bubble was iridescent, shimmering in a rainbow of colors.","t":"肥皂泡泡閃耀著彩虹般的虹彩光芒。","src":"306"},{"w":"irrelevant","p":"adj.","d":"Not related or applicable.","c":"不相關的；不切題的","s":"His comment was irrelevant to the discussion.","t":"他的評論與討論無關。","src":"386"},{"w":"isolate","p":"v.","d":"To separate from others.","c":"隔離；孤立","s":"We need to isolate the patient with the very contagious disease.","t":"我們必須隔離這位感染了高度傳染性疾病的病人。","src":"386"},{"w":"jubilant","p":"adj.","d":"Feeling or expressing great happiness or triumph.","c":"歡呼的；喜悅的","s":"The fans were jubilant after their team won the championship.","t":"球隊奪冠後，球迷們歡欣鼓舞。","src":"306"},{"w":"juxtapose","p":"v.","d":"To place or deal with close together for contrasting effect.","c":"並列","s":"The artist juxtaposed bright colors with dark shadows to create a striking image.","t":"這位藝術家將明亮的色彩與深暗的陰影並置，創造出引人注目的畫面。","src":"306"},{"w":"keen","p":"adj.","d":"Having or showing eagerness or enthusiasm.","c":"熱切的；敏銳的","s":"She was keen to learn everything about the new software program.","t":"她渴望學會這套新軟體的一切。","src":"306"},{"w":"kindle","p":"v.","d":"To start a fire or ignite excitement or interest.","c":"點燃；激起","s":"Her inspiring words kindled a passion for learning in her students.","t":"她激勵人心的話語點燃了學生對學習的熱情。","src":"306"},{"w":"labyrinthine","p":"adj.","d":"Complicated and highly intricate.","c":"錯綜複雜如迷宮的","s":"The labyrinthine plot of the novel kept readers guessing until the end.","t":"這本小說錯綜複雜的情節讓讀者猜到最後一刻。","src":"306"},{"w":"lacking","p":"adj.","d":"Not having enough of something.","c":"缺乏的","s":"The short essay was lacking in detail.","t":"這篇短文缺乏細節。","src":"386"},{"w":"laconic","p":"adj.","d":"Using very few words.","c":"簡潔的；言簡意賅的","s":"His laconic reply suggested he didn’t want to discuss the matter further.","t":"他簡短的回答暗示他不想再多談這件事。","src":"306"},{"w":"lament","p":"v.","d":"To express grief or sorrow.","c":"悲嘆；哀悼；抱怨；輓歌","s":"He lamented the loss of his childhood home after the storm.","t":"暴風雨過後，他為失去兒時的家感到悲痛。","src":"306"},{"w":"latent","p":"adj.","d":"Existing but not yet developed or visible; hidden or dormant.","c":"潛在的；隱伏的","s":"The disease remained latent in her body for several years before symptoms appeared.","t":"這種疾病在她體內潛伏了好幾年，才出現症狀。","src":"306 + 386"},{"w":"laud","p":"v.","d":"To praise highly, especially in public.","c":"稱讚；讚美","s":"The poet was lauded for her unique and poignant verses.","t":"這位詩人因獨特而感人的詩句而受到讚揚。","src":"306"},{"w":"laudable","p":"adj.","d":"Deserving praise or commendation.","c":"值得讚賞的；可嘉的","s":"Her dedication to helping the poor is truly laudable.","t":"她致力於幫助窮人，真的值得讚揚。","src":"306"},{"w":"lavish","p":"adj.","d":"Sumptuously rich, elaborate, or luxurious.","c":"慷慨的；奢華的","s":"They threw a lavish party to celebrate the milestone.","t":"他們舉辦了一場奢華的派對來慶祝這個里程碑。","src":"306"},{"w":"legitimate","p":"adj.","d":"Conforming to the law or rules; valid or justifiable.","c":"合法的；正當的","s":"The company assured its customers that the transaction was legitimate and secure.","t":"公司向顧客保證這筆交易合法又安全。","src":"306 + 386"},{"w":"lenient","p":"adj.","d":"Permissive, merciful, or tolerant.","c":"寬容的；仁慈的","s":"The teacher was lenient with late assignments, understanding students' challenges.","t":"老師對遲交的作業很寬容，能體諒學生的難處。","src":"306"},{"w":"lethargic","p":"adj.","d":"Sluggish and apathetic.","c":"昏睡的；遲鈍的","s":"After staying up all night, she felt lethargic and unmotivated.","t":"熬了一整夜之後，她覺得無精打采、提不起勁。","src":"306"},{"w":"localized","p":"adj.","d":"Restricted to a specific area or part.","c":"局部的；地方性的","s":"The infection was localized to his left lung and was treated successfully.","t":"感染只局限於他的左肺，並已成功治療。","src":"306 + 386"},{"w":"magnanimous","p":"adj.","d":"Generous or forgiving, especially toward a rival or less powerful person.","c":"寬宏大量的","s":"Despite the heated debate, she was magnanimous in victory, thanking her opponent.","t":"儘管辯論激烈，她勝利後仍寬宏大量地向對手致謝。","src":"306"}]},{"unit":18,"theme":"malicious – neutrality","cards":[{"w":"malicious","p":"adj.","d":"Intended to harm or hurt.","c":"惡意的；存心不良的","s":"His malicious behavior toward others caused a great deal of distress.","t":"他對別人的惡意行為造成了極大的痛苦。","src":"306"},{"w":"manageable","p":"adj.","d":"Able to be controlled or handled.","c":"可管理的；可應付的","s":"I'm lucky that my workload is manageable today, so I'll be home in time for dinner.","t":"我很幸運今天的工作量還應付得來，所以能及時回家吃晚餐。","src":"386"},{"w":"mandatory","p":"adj.","d":"Required or obligatory.","c":"強制性的；必須的","s":"Attendance at the meeting is mandatory for all employees.","t":"所有員工都必須出席這場會議。","src":"386"},{"w":"manipulate","p":"v.","d":"To control or influence (someone or something) cleverly or unscrupulously.","c":"操控；操縱","s":"The villain tried to manipulate the situation to his advantage.","t":"反派試圖操縱局勢，讓情況對自己有利。","src":"306"},{"w":"melancholy","p":"adj.","d":"A deep, persistent sadness or sorrow.","c":"憂鬱的；悲傷的","s":"The melancholy mood of the film left the audience reflecting on their own lives.","t":"這部電影憂鬱的氛圍讓觀眾反思自己的人生。","src":"306"},{"w":"meticulous","p":"adj.","d":"Showing great attention to detail; very careful and precise.","c":"一絲不苟的；細心的","s":"She was meticulous in preparing her notes for the exam.","t":"她一絲不苟地準備考試筆記。","src":"306"},{"w":"mimic","p":"v./adj.","d":"To imitate or copy something or someone, often to entertain or mock.","c":"模仿","s":"She could mimic the accents of people from different regions perfectly.","t":"她能完美模仿不同地區的人的口音。","src":"306 + 386"},{"w":"misanthropic","p":"adj.","d":"Disliking people or society.","c":"厭世的；憤世嫉俗的","s":"The old man was known for his misanthropic views.","t":"那位老人以厭惡人類的觀點出名。","src":"386"},{"w":"misrepresent","p":"v.","d":"To give a false impression.","c":"歪曲；誤傳","s":"The article misrepresented the facts.","t":"這篇文章歪曲了事實。","src":"386"},{"w":"mitigate","p":"v.","d":"To make less severe, serious, or painful.","c":"減輕；緩和","s":"The doctor prescribed medication to mitigate the patient's symptoms.","t":"醫生開了藥來減輕病人的症狀。","src":"306"},{"w":"moderate","p":"v./adj.","d":"To make something less extreme or intense; average in amount or degree.","c":"使溫和；適度的","s":"The coach asked the players to moderate their efforts to avoid exhaustion.","t":"教練要求球員們節制用力，以免體力耗盡。","src":"306 + 386"},{"w":"modest","p":"adj.","d":"Unassuming or humble in the estimation of one’s abilities or achievements.","c":"謙虛的；樸實的","s":"Despite his many awards, he remained modest and humble.","t":"儘管得過許多獎，他仍然謙虛低調。","src":"306"},{"w":"multifaceted","p":"adj.","d":"Having many aspects or features.","c":"多面向的；多才多藝的","s":"The housing problem is multifaceted and will take multiple solutions to solve.","t":"住房問題是多面向的，需要多種解決方案。","src":"386"},{"w":"mundane","p":"adj.","d":"Lacking interest or excitement; dull.","c":"平凡的；世俗的","s":"The routine chores felt mundane after a long week of intense work.","t":"經過一週緊湊的工作後，例行的家事顯得平凡乏味。","src":"306"},{"w":"mystifying","p":"adj.","d":"Extremely confusing or difficult to understand; baffling.","c":"令人困惑的","s":"The magician's trick was mystifying, leaving the audience in awe.","t":"魔術師的把戲令人費解，讓觀眾驚嘆不已。","src":"306"},{"w":"nebulous","p":"adj.","d":"In the form of a cloud or haze; hazy, unclear or vague.","c":"朦朧的；模糊的","s":"His explanation was so nebulous that no one understood what he meant.","t":"他的解釋含糊不清，沒有人懂他的意思。","src":"306"},{"w":"neglect","p":"v.","d":"To fail to care for properly.","c":"忽視；疏忽","s":"He neglected his responsibilities when he decided to play video games instead of clean the house.","t":"他決定打電玩而不打掃家裡，忽略了自己的責任。","src":"386"},{"w":"negligible","p":"adj.","d":"So small or unimportant as to be not worth considering.","c":"微不足道的；可忽略的","s":"The difference in price between the two options was negligible.","t":"兩個選項之間的價差微乎其微。","src":"306"},{"w":"neutrality","p":"n.","d":"The state of not taking sides.","c":"中立","s":"Switzerland maintained neutrality during World War II.","t":"瑞士在第二次世界大戰期間保持中立。","src":"386"}]},{"unit":19,"theme":"newfound – operative","cards":[{"w":"newfound","p":"adj.","d":"Recently discovered or developed.","c":"新發現的；新獲得的","s":"The recently-released prisoner enjoyed his newfound freedom.","t":"剛出獄的囚犯享受著新獲得的自由。","src":"386"},{"w":"notional","p":"adj.","d":"Existing only in theory.","c":"概念上的；假設的","s":"Because we hadn't started it, the plan was still notional.","t":"因為我們還沒開始，這個計畫仍停留在構想階段。","src":"386"},{"w":"novel","p":"adj.","d":"New and different from anything seen or experienced before; original.","c":"新穎的；新奇的","s":"His approach to the problem was novel and offered a fresh perspective.","t":"他處理這個問題的方法很新穎，提供了全新的觀點。","src":"306 + 386"},{"w":"noxious","p":"adj.","d":"Harmful, poisonous, or very unpleasant.","c":"有害的；有毒的","s":"The noxious fumes from the factory polluted the air in the nearby town.","t":"工廠排放的有毒煙霧污染了附近城鎮的空氣。","src":"306"},{"w":"nuanced","p":"adj.","d":"Showing subtle distinctions or variations in meaning, expression, or feeling.","c":"細膩的；微妙的","s":"The film's portrayal of love was nuanced, capturing the complexity of human emotion.","t":"這部電影對愛情的描寫細膩入微，捕捉到人類情感的複雜。","src":"306 + 386"},{"w":"obfuscate","p":"v.","d":"To confuse, bewilder, or make unclear.","c":"使模糊；使困惑","s":"The professor's complex explanation only served to obfuscate the topic further.","t":"教授複雜的解釋只讓這個主題更加混淆難懂。","src":"306"},{"w":"obligate","p":"v.","d":"To compel or require.","c":"使負義務；迫使","s":"The contract obligates him to pay.","t":"這份合約使他有義務付款。","src":"386"},{"w":"obscure","p":"adj./v.","d":"Not well-known or understood; unclear; to make something unclear.","c":"模糊的；默默無聞的","s":"The explanation was so obscure that no one understood what he meant.","t":"這個解釋晦澀難懂，沒有人懂他的意思。","src":"306 + 386"},{"w":"observable","p":"adj.","d":"Able to be seen or noticed.","c":"可觀察到的","s":"The rings of Saturn were observable through the telescope.","t":"透過望遠鏡可以觀察到土星環。","src":"386"},{"w":"observant","p":"adj.","d":"Quick to notice or perceive things; paying careful attention to details.","c":"善於觀察的；敏銳的","s":"She was observant enough to catch the mistake in the report before it was sent out.","t":"她觀察力敏銳，在報告寄出前就發現了錯誤。","src":"306 + 386"},{"w":"obsolete","p":"adj.","d":"No longer produced or used; out of date.","c":"過時的；淘汰的；廢棄的","s":"The technology quickly became obsolete as newer models were introduced.","t":"隨著新型號推出，這項技術很快就過時了。","src":"306 + 386"},{"w":"obstructed","p":"adj.","d":"Blocked or hindered.","c":"受阻的；被堵塞的","s":"We couldn't leave town because the road was obstructed by fallen trees.","t":"道路被倒下的樹木阻擋，我們無法離開小鎮。","src":"386"},{"w":"occupy","p":"v.","d":"To take up space or time.","c":"佔用；佔據","s":"The kids occupied themselves with games.","t":"孩子們玩遊戲自得其樂。","src":"386"},{"w":"oddity","p":"n.","d":"Something unusual or strange.","c":"怪事；奇特的東西","s":"The museum displayed an interesting oddity.","t":"博物館展出了一件有趣的奇特物品。","src":"386"},{"w":"offhand","p":"adj.","d":"Done or said without preparation or thought; casual.","c":"隨口的；漫不經心的","s":"His offhand remark upset many of the employees, even though he didn’t mean harm.","t":"他隨口說出的話讓許多員工不高興，即使他並無惡意。","src":"306 + 386"},{"w":"ominous","p":"adj.","d":"Giving the impression that something bad or unpleasant is going to happen.","c":"不祥的；凶兆的","s":"The dark clouds gave an ominous feeling to the day.","t":"烏雲讓這一天籠罩著不祥的感覺。","src":"306"},{"w":"omnipotent","p":"adj.","d":"Almighty and all powerful.","c":"全能的","s":"Gods are omnipotent beings who can control human destiny.","t":"神是能掌控人類命運的全能存在。","src":"386"},{"w":"onset","p":"n.","d":"The beginning or early stages.","c":"開始；發作","s":"At the onset of her career as a lawyer, things were looking up.","t":"她剛開始當律師的時候，一切看起來都很順利。","src":"386"},{"w":"operative","p":"adj./n.","d":"In operation or use; a person actively involved in an activity or operation.","c":"運作中的；特工","s":"The new software is fully operative and ready for use in all departments.","t":"新軟體已全面運作，可供所有部門使用。","src":"306 + 386"}]},{"unit":20,"theme":"opulent – permanent","cards":[{"w":"opulent","p":"adj.","d":"Wealthy, luxurious, or lavish.","c":"奢華的；富麗堂皇的","s":"The opulent palace was filled with fine art and golden decor.","t":"那座富麗堂皇的宮殿裡擺滿了精美的藝術品和金色裝飾。","src":"306"},{"w":"originate","p":"v.","d":"To begin or come into existence; to create or start something.","c":"發源；創立","s":"The idea for the project originated from a discussion at last year’s conference.","t":"這個計畫的構想源自去年研討會上的一次討論。","src":"306"},{"w":"ornamental","p":"adj.","d":"Serving as decoration rather than for a practical purpose.","c":"裝飾性的","s":"The vase was purely ornamental, with no real use other than decoration.","t":"這只花瓶純粹是裝飾用的，除了裝飾沒有實際用途。","src":"306 + 386"},{"w":"oscillate","p":"v.","d":"To move or swing back and forth in a regular rhythm.","c":"擺動；搖擺","s":"The fan oscillated in the corner, providing a cool breeze in the room.","t":"角落的電風扇來回擺動，為房間送來涼風。","src":"306"},{"w":"oust","p":"v.","d":"To remove or force out of (usu. a position or office).","c":"驅逐；罷免","s":"Sick and tired of putting up with his bad moods, the pirates ousted their captain.","t":"受夠了船長的壞脾氣，海盜們把他趕下台。","src":"386"},{"w":"outstrip","p":"v.","d":"To surpass or exceed.","c":"超過；勝過；跑過","s":"Sales of my new novel outstripped all expectations.","t":"我新小說的銷量超出了所有人的預期。","src":"386"},{"w":"overcome","p":"v.","d":"To succeed in dealing with a problem.","c":"克服","s":"She overcame her fear of public speaking and was able to deliver her remarks.","t":"她克服了對公開演講的恐懼，順利發表了談話。","src":"386"},{"w":"overlook","p":"v.","d":"To fail to notice or consider.","c":"忽略","s":"The officer overlooked an important detail that would have helped solve the crime.","t":"那名警官忽略了一個本可幫助破案的重要細節。","src":"386"},{"w":"overreact","p":"v.","d":"To respond too strongly.","c":"反應過度","s":"My sister overreacted to our parents' criticism of her outfit.","t":"我姊姊對父母批評她的穿著反應過度。","src":"386"},{"w":"overshadow","p":"v.","d":"To be more important than something else.","c":"遮蔽；使相形失色；使黯然失色","s":"His success overshadowed his past failures.","t":"他的成功使過去的失敗相形失色。","src":"386"},{"w":"overt","p":"adj.","d":"Done or shown openly; plainly apparent.","c":"公開的；明顯的","s":"Her overt display of affection was noticed by everyone in the room.","t":"她公開地表達愛意，房間裡每個人都注意到了。","src":"306"},{"w":"overtly","p":"adv.","d":"Openly and clearly.","c":"公開地；明顯地","s":"He overtly expressed his disapproval by telling me what he thought.","t":"他直接告訴我他的想法，公開表示不贊同。","src":"386"},{"w":"overwhelmed","p":"adj.","d":"Feeling excessive stress or emotion.","c":"不堪重負的；難以承受的","s":"Agatha felt overwhelmed by her workload and had no idea how she'd finish it all in time.","t":"阿嘉莎被工作量壓得喘不過氣，完全不知道要怎麼及時做完。","src":"386"},{"w":"palpable","p":"adj.","d":"Able to be touched or felt; tangible; clear to the mind or senses.","c":"明顯的；可感知的","s":"The tension in the room was palpable as everyone awaited the decision.","t":"大家等待決定時，房間裡的緊張氣氛明顯可感。","src":"306"},{"w":"paramount","p":"adj.","d":"Predominant, superior, most important.","c":"首要的；至高無上的","s":"Our paramount concern is the safety of our employees.","t":"我們最重要的考量是員工的安全。","src":"386"},{"w":"paucity","p":"n.","d":"The presence of something in small amounts or numbers; scarcity.","c":"缺乏；不足","s":"The paucity of evidence made it difficult to reach a conclusion in the case.","t":"證據的缺乏讓此案難以做出結論。","src":"306 + 386"},{"w":"perceive","p":"v.","d":"To become aware of something.","c":"察覺；感知；理解","s":"She perceived a hint of sadness in his voice.","t":"她察覺到他的聲音裡帶著一絲悲傷。","src":"386"},{"w":"peripheral","p":"adj.","d":"Related to or located on the edge of something; secondary or less important.","c":"邊緣的；次要的","s":"The meeting focused on the main issues, with peripheral topics saved for later.","t":"會議聚焦在主要議題上，次要的話題留待之後討論。","src":"306 + 386"},{"w":"permanent","p":"adj.","d":"Lasting indefinitely.","c":"永久的","s":"The marker left a permanent stain on my favorite shirt that I won't be able ot get out.","t":"麥克筆在我最喜歡的襯衫上留下了洗不掉的永久污漬。","src":"386"}]},{"unit":21,"theme":"perpetual – preserve","cards":[{"w":"perpetual","p":"adj.","d":"Continuing forever or indefinitely.","c":"永久的；不斷的","s":"The con artist lived in perpetual fear of being arrested.","t":"那名騙子一直活在害怕被逮捕的恐懼中。","src":"386"},{"w":"persevere","p":"v.","d":"To continue in a course of action even in the face of difficulty or opposition.","c":"堅持不懈；不屈不撓","s":"She persevered through years of study to achieve her dream of becoming a doctor.","t":"她堅持不懈地苦讀多年，實現了成為醫生的夢想。","src":"306"},{"w":"persistent","p":"adj.","d":"Continuing firmly or steadily in a course of action despite difficulties or opposition.","c":"堅持不懈的；持續的","s":"His persistent efforts to improve the system eventually paid off.","t":"他不斷努力改善這套系統，終於有了回報。","src":"306 + 386"},{"w":"pervasive","p":"adj.","d":"Spreading widely throughout an area or a group of people.","c":"瀰漫的；普遍存在的","s":"The pervasive scent of freshly baked cookies filled the entire house.","t":"剛烤好的餅乾香味瀰漫了整個屋子。","src":"306"},{"w":"polarized","p":"adj.","d":"Divided sharply into opposing groups or views.","c":"兩極化的","s":"The debate was highly polarized, with each side refusing to compromise.","t":"這場辯論嚴重兩極化，雙方都拒絕妥協。","src":"306"},{"w":"popularize","p":"v.","d":"To make widely known.","c":"使普及；推廣","s":"The internet popularized online shopping.","t":"網際網路使網路購物普及。","src":"386"},{"w":"postulate","p":"v.","d":"To assume or propose a theory.","c":"假定；假設","s":"Scientists postulated a new hypothesis for the origin of the universe.","t":"科學家針對宇宙起源提出了新的假說。","src":"386"},{"w":"pragmatic","p":"adj.","d":"Dealing with things sensibly and realistically based on practical considerations.","c":"務實的；實用主義的","s":"His pragmatic approach to solving the problem saved both time and resources.","t":"他務實的解決方法節省了時間和資源。","src":"306 + 386"},{"w":"praise","p":"v.","d":"To express approval or admiration.","c":"讚美；稱讚","s":"The teacher praised the students’ hard work.","t":"老師稱讚學生的努力。","src":"386"},{"w":"precarious","p":"adj.","d":"Uncertain or unstable.","c":"不穩定的；岌岌可危的","s":"The goat was perched on a precarious edge of the cliff.","t":"那隻山羊站在懸崖岌岌可危的邊緣上。","src":"386"},{"w":"preclude","p":"v.","d":"To prevent from happening.","c":"排除；防止","s":"Dylan's injury precluded him from playing in the soccer match.","t":"迪倫的傷使他無法參加足球比賽。","src":"386"},{"w":"precocious","p":"adj.","d":"Showing unusually early development, especially mental or intellectual.","c":"早熟的","s":"The precocious child could read by the age of three.","t":"那個早熟的孩子三歲就會閱讀。","src":"306"},{"w":"predatory","p":"adj.","d":"Seeking to exploit or harm others, often for personal gain; related to predators.","c":"掠奪性的；捕食性的","s":"The predatory behavior of the company led to lawsuits from employees.","t":"這家公司掠奪性的行為引發了員工的訴訟。","src":"306 + 386"},{"w":"predetermine","p":"adj.","d":"To decide or determine in advance, especially by fate or a higher power.","c":"預先決定","s":"His actions seemed predetermined, as if everything had already been decided for him.","t":"他的行動似乎是預先注定的，彷彿一切早已為他決定好了。","src":"306"},{"w":"predetermined","p":"adj.","d":"Decided in advance.","c":"預先決定的","s":"The outcome seemed predetermined and that we could do nothing to change it.","t":"結果似乎早已注定，我們無力改變。","src":"386"},{"w":"predict","p":"v.","d":"To say what will happen in the future.","c":"預測","s":"Meteorologists predict rain tomorrow.","t":"氣象學家預測明天會下雨。","src":"386"},{"w":"premeditated","p":"adj.","d":"Planned beforehand.","c":"預謀的","s":"Because the man had planned the theft for weeks, it was obvious the crime was premeditated.","t":"那名男子策劃這起竊案好幾週，顯然這是預謀犯罪。","src":"386"},{"w":"prescribe","p":"v.","d":"To recommend or authorize the use of something, especially a treatment or remedy.","c":"開處方；規定","s":"The doctor will prescribe a course of antibiotics to treat the infection.","t":"醫生會開一個療程的抗生素來治療感染。","src":"306 + 386"},{"w":"preserve","p":"v.","d":"To keep something in its original state.","c":"保存；維護","s":"The builders worked to preserve the house's original decorations.","t":"建築工人努力保存房子原有的裝飾。","src":"386"}]},{"unit":22,"theme":"presume – quarrel","cards":[{"w":"presume","p":"v.","d":"To assume something to be true.","c":"假定；推測","s":"I presume he will be late to the party.","t":"我推測他參加派對會遲到。","src":"386"},{"w":"prevail","p":"v.","d":"To prove more powerful or superior; to win or succeed after a struggle.","c":"獲勝；盛行","s":"After a long legal battle, justice finally prevailed.","t":"經過漫長的法律戰，正義終於獲勝。","src":"306 + 386"},{"w":"preventable","p":"adj.","d":"Able to be avoided.","c":"可預防的","s":"Many diseases are preventable with vaccines.","t":"許多疾病可以透過疫苗預防。","src":"386"},{"w":"probability","p":"n.","d":"Likelihood of something happening.","c":"可能性","s":"When you live in the desert, there's almost always a low probability of rain.","t":"住在沙漠裡，下雨的機率幾乎總是很低。","src":"386"},{"w":"proclaim","p":"v.","d":"To announce officially or publicly.","c":"宣告；宣布","s":"The president will proclaim the new law during the ceremony tomorrow.","t":"總統將在明天的典禮上宣布新法律。","src":"306 + 386"},{"w":"prodigal","p":"adj.","d":"Spending money or resources freely and recklessly; wasteful.","c":"揮霍的；浪費的","s":"The prodigal son squandered his inheritance in a short amount of time.","t":"那個揮霍無度的兒子在短時間內就把遺產揮霍殆盡。","src":"306"},{"w":"produce","p":"v.","d":"To create or generate something.","c":"生產；製造","s":"The Ford factory produces thousands of cars each year.","t":"福特工廠每年生產數千輛汽車。","src":"386"},{"w":"profusion","p":"n.","d":"A large quantity of something.","c":"豐富；大量","s":"The garden had a profusion of flowers every spring.","t":"每年春天，花園裡都開滿了大量的花朵。","src":"386"},{"w":"prolific","p":"adj.","d":"Producing a large amount of something.","c":"多產的；高產的","s":"The prolific writer published a new novel every year.","t":"那位多產的作家每年都出版一本新小說。","src":"306"},{"w":"prolong","p":"v.","d":"To extend in duration.","c":"延長","s":"He tried to prolong the meeting from one hour to two.","t":"他試圖把會議從一小時延長到兩小時。","src":"386"},{"w":"prominent","p":"adj.","d":"Important or well-known.","c":"知名的；顯著的","s":"Marie Curie was a prominent scientist who won many awards.","t":"居禮夫人是一位得過許多獎項的傑出科學家。","src":"386"},{"w":"propagate","p":"v.","d":"To breed or spread something, especially ideas or knowledge.","c":"傳播；繁殖","s":"The organization works to propagate awareness about climate change.","t":"這個組織致力於傳播對氣候變遷的認識。","src":"306"},{"w":"proponent","p":"n.","d":"A person who advocates or supports a cause or idea.","c":"支持者；提倡者","s":"She was a leading proponent of environmental conservation.","t":"她是環境保育的主要擁護者。","src":"306 + 386"},{"w":"prosaic","p":"adj.","d":"Lacking poetic beauty; dull or ordinary.","c":"平淡無奇的；乏味的","s":"His prosaic writing style failed to capture the audience’s interest.","t":"他平淡無奇的寫作風格沒能引起讀者的興趣。","src":"306"},{"w":"proscribe","p":"v.","d":"To forbid, especially by law; to condemn or outlaw.","c":"禁止；取締","s":"The government decided to proscribe the use of the harmful chemical.","t":"政府決定禁止使用這種有害化學物質。","src":"306"},{"w":"provoke","p":"v.","d":"To stir up or incite.","c":"激怒；激起","s":"Miriam's rude words provoked an argument.","t":"米莉安無禮的話引發了一場爭吵。","src":"386"},{"w":"prudently","p":"adv.","d":"In a wise or careful manner.","c":"謹慎地；明智地","s":"My grandmother always prudently saved money for emergencies.","t":"我祖母總是謹慎地存錢以備不時之需。","src":"386"},{"w":"quantity","p":"n.","d":"An amount or number.","c":"數量","s":"The pudding recipe requires a small quantity of sugar.","t":"這個布丁食譜只需要少量的糖。","src":"386"},{"w":"quarrel","p":"n.","d":"An angry argument or dispute.","c":"爭吵","s":"The couple had a loud quarrel over money.","t":"這對夫妻為了錢大聲爭吵。","src":"386"}]},{"unit":23,"theme":"quell – refute","cards":[{"w":"quell","p":"v.","d":"To put an end to something, usually by force.","c":"平息；鎮壓","s":"The police were able to quell the riot before it escalated further.","t":"警方在暴動擴大之前成功平息了它。","src":"306"},{"w":"questionable","p":"adj.","d":"Doubtful or uncertain.","c":"可疑的；有問題的","s":"Despite claiming to want to help people, the politician's motives were questionable.","t":"儘管聲稱想幫助人民，那位政治人物的動機令人懷疑。","src":"386"},{"w":"quixotic","p":"adj.","d":"Extremely idealistic; unrealistic and impractical.","c":"不切實際的；唐吉訶德式的","s":"His quixotic dreams of becoming a superhero were charming but unrealistic.","t":"他想成為超級英雄的不切實際的夢想很可愛，卻不實際。","src":"306"},{"w":"ramify","p":"v.","d":"To split into two or more branches.","c":"分支；分岔","s":"Cars ramified throughout the world in the twentieth century.","t":"二十世紀時，汽車在全世界擴散開來。","src":"386"},{"w":"rarely","p":"adv.","d":"Infrequently or seldom.","c":"很少；罕見地","s":"My sister rarely eats fast food.","t":"我妹妹很少吃速食。","src":"386"},{"w":"rationalize","p":"v.","d":"To justify an action with reasoning.","c":"合理化；為…找藉口","s":"He tried to rationalize his mistake by explaining his thought process.","t":"他試圖解釋自己的思考過程，為錯誤找合理的藉口。","src":"386"},{"w":"rebellion","p":"n.","d":"An act of resistance against authority.","c":"反叛；叛亂","s":"The peasants led a rebellion against the king.","t":"農民們發動了一場反抗國王的叛亂。","src":"386"},{"w":"recalcitrant","p":"adj.","d":"Stubbornly resistant to authority or control.","c":"桀驁不馴的；頑抗的","s":"The recalcitrant student refused to follow the teacher's instructions.","t":"那個頑抗不馴的學生拒絕聽從老師的指示。","src":"306 + 386"},{"w":"recant","p":"v.","d":"To withdraw or retract a statement or belief, especially formally.","c":"撤回(聲明)；放棄(信仰)","s":"After further investigation, he decided to recant his earlier statement.","t":"經過進一步調查後，他決定撤回先前的說法。","src":"306 + 386"},{"w":"receptive","p":"adj.","d":"Open to new ideas.","c":"樂於接受的","s":"The new dancer was receptive to feedback.","t":"新來的舞者樂於接受意見。","src":"386"},{"w":"reciprocate","p":"v.","d":"To respond to a gesture or action by making a corresponding one; to give and receive in return.","c":"回報；互惠","s":"She reciprocated his kindness by inviting him to her birthday party.","t":"她邀請他參加自己的生日派對，以回報他的善意。","src":"306 + 386"},{"w":"recognizable","p":"adj.","d":"Easily identified.","c":"可辨識的；易識別的","s":"The Nike logo is instantly recognizable.","t":"耐吉的標誌一眼就能認出來。","src":"386"},{"w":"recondite","p":"adj.","d":"Little known; obscure, difficult to understand.","c":"深奧的；隱蔽的","s":"The professor’s recondite lecture left many students confused.","t":"教授深奧難懂的講課讓許多學生一頭霧水。","src":"306"},{"w":"rectify","p":"v.","d":"To correct or fix something.","c":"糾正；矯正","s":"She tried to rectify her mistake with an apology.","t":"她試著用道歉來糾正自己的錯誤。","src":"386"},{"w":"redefine","p":"v.","d":"To change the meaning of something.","c":"重新定義","s":"The company redefined its mission.","t":"這家公司重新定義了它的使命。","src":"386"},{"w":"redress","p":"v.","d":"To set right or remedy.","c":"糾正；補償","s":"They sought to redress past injustices.","t":"他們設法糾正過去的不公。","src":"386"},{"w":"reform","p":"v.","d":"To improve by making changes.","c":"改革","s":"The government promised to reform the healthcare system.","t":"政府承諾改革醫療體系。","src":"386"},{"w":"refuse","p":"v.","d":"To decline or reject.","c":"拒絕","s":"Emilia refused the job offer.","t":"艾蜜莉亞拒絕了這份工作機會。","src":"386"},{"w":"refute","p":"v.","d":"To prove something to be false or incorrect by providing evidence or argument.","c":"駁斥；反駁","s":"The lawyer refuted the accusations with solid evidence.","t":"律師以確鑿的證據駁斥了指控。","src":"306 + 386"}]},{"unit":24,"theme":"regrettable – resolve","cards":[{"w":"regrettable","p":"adj.","d":"Causing sorrow or disappointment.","c":"令人遺憾的","s":"Forgetting my boyfriend's birthday was a regrettable mistake.","t":"忘記男友的生日是個令人遺憾的錯誤。","src":"386"},{"w":"regulate","p":"v.","d":"To control or manage.","c":"規範；管制","s":"The government regulates nuclear energy facilities.","t":"政府管理核能設施。","src":"386"},{"w":"reject","p":"v.","d":"To dismiss or refuse to accept.","c":"拒絕；駁回","s":"She rejected her boyfriend's proposal.","t":"她拒絕了男友的求婚。","src":"386"},{"w":"rejuvenate","p":"v.","d":"To make something or someone look or feel younger, fresher, or more lively.","c":"使恢復活力；使年輕化","s":"A good night's sleep can rejuvenate your mind and body.","t":"一夜好眠能讓你的身心恢復活力。","src":"306"},{"w":"relevant","p":"adj.","d":"Closely connected or appropriate to the matter at hand; important.","c":"相關的","s":"Her comments were relevant to the discussion and helped clarify the issue.","t":"她的意見與討論相關，有助於釐清問題。","src":"306"},{"w":"relinquish","p":"v.","d":"To voluntarily give up or let go of something.","c":"放棄；交出","s":"He was forced to relinquish control of the project after his failure to meet deadlines.","t":"由於沒能趕上截止期限，他被迫放棄對這個計畫的掌控權。","src":"306"},{"w":"relocate","p":"v.","d":"To move to a new place.","c":"搬遷","s":"The dentist relocated to a bigger office.","t":"那位牙醫搬到了更大的診所。","src":"386"},{"w":"remorse","p":"n.","d":"Deep regret or guilt for a wrong committed.","c":"懊悔；悔恨","s":"He felt great remorse for his actions and apologized profusely.","t":"他對自己的行為深感懊悔，一再道歉。","src":"306"},{"w":"renounce","p":"v.","d":"To formally give up or reject a belief, cause, or claim.","c":"放棄；宣布放棄","s":"He chose to renounce his citizenship in favor of a different country.","t":"他選擇放棄自己的公民身分，改入另一個國家的國籍。","src":"306 + 386"},{"w":"repercussion","p":"n.","d":"An unintended consequence or effect, often negative.","c":"後果；餘波","s":"The repercussion of her decision was felt by everyone in the organization.","t":"她的決定所帶來的影響，組織裡的每個人都感受到了。","src":"306"},{"w":"replenish","p":"v.","d":"To refill or restore.","c":"補充；重新裝滿","s":"After we finished the lemonade, the hostess replenished the pitcher.","t":"我們喝完檸檬汁後，女主人又把水壺補滿了。","src":"386"},{"w":"replicable","p":"adj.","d":"Capable of being reproduced or repeated.","c":"可複製的；可重複的","s":"The experiment was designed to be replicable, allowing others to verify the results.","t":"這個實驗設計成可重複進行，讓其他人能驗證結果。","src":"306 + 386"},{"w":"representative","p":"n.","d":"A person acting on behalf of others.","c":"代表","s":"The company's representative spoke at the meeting.","t":"公司的代表在會議上發言。","src":"386"},{"w":"repress","p":"v.","d":"To suppress or hold back.","c":"壓抑；鎮壓","s":"Although devastated, Jalen repressed his emotions.","t":"儘管心碎不已，傑倫還是壓抑住了自己的情緒。","src":"386"},{"w":"reprieve","p":"n.","d":"A temporary relief or delay.","c":"緩刑；暫緩","s":"Because the defendant needed surgery, the judge granted a reprieve.","t":"由於被告需要動手術，法官准予暫緩執行。","src":"386"},{"w":"repudiate","p":"v.","d":"To reject, deny, or disown something, especially a belief or opinion.","c":"拒絕；否認；與…斷絕關係","s":"The politician repudiated the claims made against him during the campaign.","t":"那位政治人物駁斥競選期間針對他的指控。","src":"306 + 386"},{"w":"rescind","p":"v.","d":"To revoke, cancel, or repeal a law, order, or agreement.","c":"撤銷；廢除","s":"The company decided to rescind the job offer after reviewing his application.","t":"審查他的申請後，公司決定撤銷這份工作錄取。","src":"306"},{"w":"resilient","p":"adj.","d":"Able to recover quickly from difficulties; tough and adaptable.","c":"有韌性的；能迅速恢復的","s":"She showed resilient strength after the accident, returning to work soon after.","t":"她在意外後展現出堅韌的力量，很快就回到工作崗位。","src":"306 + 386"},{"w":"resolve","p":"v.","d":"To find a solution.","c":"決心；堅定","s":"The warring siblings eventually resolved their differences.","t":"爭吵不休的兄弟姊妹最後化解了彼此的分歧。","src":"386"}]},{"unit":25,"theme":"responsive – scrupulous","cards":[{"w":"responsive","p":"adj.","d":"Reacting quickly or positively.","c":"回應迅速的；反應靈敏的","s":"The team wanted to improve and was very responsive to feedback.","t":"這個團隊想要進步，對意見反應非常積極。","src":"386"},{"w":"restless","p":"adj.","d":"Unable to rest or relax; constantly moving or active due to anxiety or agitation.","c":"不安分的；坐立不安的","s":"He felt restless during the long wait and couldn’t sit still.","t":"漫長的等待讓他坐立不安，一刻也坐不住。","src":"306"},{"w":"restore","p":"v.","d":"To bring back to original condition.","c":"恢復；修復","s":"The architecture team carefully restored the old house.","t":"建築團隊小心翼翼地修復了那棟老房子。","src":"386"},{"w":"restrain","p":"v.","d":"To hold back or limit.","c":"抑制；約束","s":"Even though Tom was furious, he restrained his anger.","t":"雖然湯姆氣炸了，他還是克制住了怒氣。","src":"386"},{"w":"restrained","p":"adj.","d":"Controlled, limited, or held back; not excessive or extreme in expression.","c":"克制的；含蓄的","s":"His restrained behavior at the meeting showed professionalism and composure.","t":"他在會議上克制的舉止展現出專業與沉著。","src":"306"},{"w":"retain","p":"v.","d":"To keep or hold onto.","c":"保留；保持","s":"I use this pitcher to retain water for my herb garden.","t":"我用這個水壺儲存澆香草園的水。","src":"386"},{"w":"retaliate","p":"v.","d":"To respond to an attack.","c":"報復","s":"After Celia yelled at Dom, he retaliated with a counterattack.","t":"西莉亞對多姆大吼之後，他以反擊報復。","src":"386"},{"w":"reticent","p":"adj.","d":"Not revealing one’s thoughts or feelings readily; reserved.","c":"沉默寡言的；保守的","s":"He was reticent about sharing personal details during the interview.","t":"面試時，他不願透露個人細節。","src":"306 + 386"},{"w":"revere","p":"v.","d":"To feel deep respect or admiration for something or someone.","c":"尊崇；敬畏","s":"They revered their teacher for her wisdom and kindness.","t":"他們因老師的智慧與仁慈而敬重她。","src":"306"},{"w":"rigorous","p":"adj.","d":"Strict and demanding, requiring a high level of effort and precision.","c":"嚴格的；嚴謹的","s":"The rigorous training schedule prepared the athletes for the competition.","t":"嚴格的訓練計畫讓運動員為比賽做好了準備。","src":"306"},{"w":"rousing","p":"adj.","d":"Exciting or stirring.","c":"振奮人心的","s":"The speaker gave a rousing speech that brought the audience to its feet.","t":"演講者發表了一場激勵人心的演說，讓聽眾起立喝采。","src":"386"},{"w":"rudimentary","p":"adj.","d":"Involving or limited to basic principles; simple or primitive.","c":"基本的；初步的","s":"His rudimentary understanding of the subject required extra tutoring.","t":"他對這個科目只有粗淺的理解，需要額外的家教。","src":"306 + 386"},{"w":"sagacious","p":"adj.","d":"Having or showing keen mental discernment and good judgment.","c":"睿智的；有遠見的","s":"The sagacious leader made decisions that benefitted the entire community.","t":"這位睿智的領袖做出了讓整個社區受益的決定。","src":"306"},{"w":"salient","p":"adj.","d":"Most noticeable or important; prominent.","c":"顯著的；突出的","s":"The salient features of the landscape included towering mountains and vast deserts.","t":"這片地景最顯著的特色包括高聳的山脈和廣闊的沙漠。","src":"306"},{"w":"sanction","p":"v.","d":"To authorize or approve.","c":"批准；認可","s":"The government sanctioned the project so construction will start soon.","t":"政府批准了這項計畫，所以很快就會動工。","src":"386"},{"w":"sanguine","p":"adj.","d":"Optimistic or hopeful.","c":"樂觀的；充滿希望的","s":"He remained sanguine despite repeated setbacks.","t":"儘管一再受挫，他依然保持樂觀。","src":"386"},{"w":"saturate","p":"v.","d":"To soak or fill completely.","c":"浸透；使飽和","s":"The sponge was saturated with water.","t":"海綿吸飽了水。","src":"386"},{"w":"scorn","p":"v.","d":"To look down on with disdain.","c":"輕蔑；鄙視","s":"It’s difficult for me not to scorn those who use improper grammar.","t":"我很難不輕視那些文法用錯的人。","src":"386"},{"w":"scrupulous","p":"adj.","d":"Diligent, thorough, and extremely attentive to details, often because of a strong moral code.","c":"一絲不苟的；嚴謹的；正直的","s":"The scrupulous lawyer reviewed every document before submission.","t":"那位一絲不苟的律師在提交前檢查了每一份文件。","src":"306"}]},{"unit":26,"theme":"scrutinize – stark","cards":[{"w":"scrutinize","p":"v.","d":"To examine closely.","c":"仔細檢查；審查","s":"I'm going to have my lawyer scrutinize the contract.","t":"我要請律師仔細審查這份合約。","src":"386"},{"w":"sear","p":"v.","d":"To burn or scorch the surface of something with intense heat.","c":"燒灼；煎烤","s":"The chef seared the steak to lock in its juices.","t":"主廚把牛排表面煎焦，以鎖住肉汁。","src":"306"},{"w":"secretive","p":"adj.","d":"Keeping things hidden.","c":"隱密的；守口如瓶的","s":"He was secretive about his plans for Valentine's Day.","t":"他對情人節的計畫守口如瓶。","src":"386"},{"w":"sensitive","p":"adj.","d":"Easily affected or aware.","c":"敏感的","s":"She is very sensitive to criticism.","t":"她對批評非常敏感。","src":"386"},{"w":"sequester","p":"v.","d":"To isolate or hide away (someone or something).","c":"使隔離；隔絕；扣押","s":"The jury was sequestered during the trial to avoid outside influence.","t":"審判期間陪審團被隔離，以避免受到外界影響。","src":"306"},{"w":"serene","p":"adj.","d":"Calm, peaceful, and untroubled.","c":"寧靜的；安詳的","s":"The serene landscape provided the perfect setting for a quiet afternoon.","t":"寧靜的風景為安靜的午後提供了完美的場景。","src":"306"},{"w":"shrewd","p":"adj.","d":"Having or showing sharp judgment and common sense.","c":"精明的；機靈的","s":"The shrewd investor made decisions that increased his wealth.","t":"那位精明的投資人做出了讓財富增加的決策。","src":"306"},{"w":"simulate","p":"v.","d":"To imitate the appearance or character of something, typically for training or research purposes.","c":"模擬","s":"The flight simulator allowed the pilot to simulate emergency scenarios.","t":"飛行模擬器讓飛行員能模擬緊急狀況。","src":"306 + 386"},{"w":"sincerity","p":"n.","d":"The quality of being genuine.","c":"真誠","s":"His sincerity was evident in his speech.","t":"他的演講中流露出真誠。","src":"386"},{"w":"sinuous","p":"adj.","d":"Having many curves and turns; winding.","c":"蜿蜒的；曲折的","s":"The sinuous road wound through the forest, offering breathtaking views.","t":"蜿蜒的道路穿過森林，沿途景色令人屏息。","src":"306"},{"w":"skeptical","p":"adj.","d":"Doubtful or inclined to question accepted beliefs or statements.","c":"懷疑的","s":"She was skeptical of the new diet fad and wanted to see more evidence before trying it.","t":"她對新流行的飲食法抱持懷疑，想先看到更多證據再嘗試。","src":"306 + 386"},{"w":"sophisticated","p":"adj.","d":"Complex or refined.","c":"複雜精密的；世故的","s":"The building's design was intricate and sophisticated.","t":"這棟建築的設計精巧而複雜。","src":"386"},{"w":"soporific","p":"adj.","d":"Tending to induce sleep or drowsiness.","c":"催眠的；令人昏昏欲睡的","s":"The soporific lecture made it difficult to stay awake.","t":"那堂令人昏昏欲睡的課讓人很難保持清醒。","src":"306"},{"w":"span","p":"n.","d":"The extent or length of something.","c":"範圍；期間","s":"The Golden Gate Bridge has a long span.","t":"金門大橋的跨距很長。","src":"386"},{"w":"sparingly","p":"adv.","d":"Insufficiently, meagerly, or in a restricted manner.","c":"節省地；少量地","s":"Due to my blood pressure, I must eat salt sparingly.","t":"由於血壓的關係，我必須少量攝取鹽分。","src":"386"},{"w":"speculate","p":"v.","d":"To form a theory or conjecture without sufficient evidence; to guess.","c":"推測；臆測","s":"They speculated about the cause of the delay but had no solid information.","t":"他們推測延誤的原因，但沒有確切的資訊。","src":"306 + 386"},{"w":"spurious","p":"adj.","d":"Not being what it purports to be; false or fake.","c":"虛假的；偽造的","s":"His spurious claims were quickly debunked by the authorities.","t":"他虛假的說法很快就被當局揭穿了。","src":"306 + 386"},{"w":"stagnant","p":"adj.","d":"Showing no activity or change; dull and inactive.","c":"停滯的；不流動的","s":"The stagnant water in the pond bred mosquitoes.","t":"池塘裡不流動的死水孳生了蚊子。","src":"306"},{"w":"stark","p":"adj.","d":"Very plain; devoid of any details or features.","c":"荒涼的；明顯的","s":"Looking out at the stark landscape, I felt a keen sense of isolation.","t":"望著荒涼的景色，我強烈感受到孤獨。","src":"386"}]},{"unit":27,"theme":"stimulate – synchronize","cards":[{"w":"stimulate","p":"v.","d":"To encourage or provoke a response or activity; to make something more active or intense.","c":"刺激；激勵","s":"The music helped to stimulate their creativity during the brainstorming session.","t":"音樂在腦力激盪時幫助激發了他們的創造力。","src":"306"},{"w":"strenuously","p":"adv.","d":"With great effort.","c":"竭力地；激烈地","s":"She strenuously denied the accusations against her.","t":"她極力否認對她的指控。","src":"386"},{"w":"sturdily","p":"adv.","d":"Strongly or solidly.","c":"堅固地；結實地","s":"The chair was sturdily built and had no chance of breaking.","t":"這張椅子做得很堅固，絕不可能壞掉。","src":"386"},{"w":"stymie","p":"v.","d":"To hinder or block.","c":"阻礙；妨礙","s":"The restoration project was stymied by a lack of funds.","t":"這項修復計畫因缺乏資金而受阻。","src":"386"},{"w":"subjugate","p":"v.","d":"To bring under domination or control, often by force.","c":"征服；降伏","s":"The conquerors sought to subjugate the native population.","t":"征服者企圖征服當地的原住民。","src":"306"},{"w":"substantial","p":"adj.","d":"Of considerable importance, size, or worth; significant.","c":"相當大的；重要的","s":"The company made a substantial profit this quarter, far exceeding expectations.","t":"這家公司本季獲得了可觀的利潤，遠超出預期。","src":"306 + 386"},{"w":"subtle","p":"adj.","d":"Delicate or precise, difficult to perceive or understand; understated.","c":"微妙的；精細的","s":"The artist used subtle colors to create an intricate design.","t":"這位藝術家用細微的色彩創造出精巧的設計。","src":"306 + 386"},{"w":"succinct","p":"adj.","d":"Briefly and clearly expressed; concise.","c":"簡明的；簡潔的","s":"Her succinct answer saved a lot of time during the meeting.","t":"她簡潔的回答在會議中節省了許多時間。","src":"306"},{"w":"succumb","p":"v.","d":"To yield or give in to something, such as a temptation or pressure; to die from an illness or injury.","c":"屈服；死於","s":"After a long battle with the disease, he eventually succumbed to his illness.","t":"與疾病長期搏鬥之後，他終究不敵病魔。","src":"306 + 386"},{"w":"superficial","p":"adj.","d":"Existing or occurring at or on the surface; lacking depth or substance.","c":"表面的；膚淺的","s":"The report provided only a superficial analysis of the issue.","t":"這份報告對這個問題只提供了膚淺的分析。","src":"306 + 386"},{"w":"supplement","p":"v./n.","d":"To add something extra to complete or enhance something else.","c":"補充；補充品","s":"She decided to supplement her diet with vitamins to boost her energy levels.","t":"她決定用維他命補充飲食，以提升精力。","src":"306 + 386"},{"w":"surmise","p":"v.","d":"To suppose or guess something without sufficient evidence; to make an assumption.","c":"猜測；臆測","s":"Based on the evidence, we can only surmise that the suspect is guilty.","t":"根據證據，我們只能推測嫌犯有罪。","src":"306 + 386"},{"w":"surpass","p":"v.","d":"To exceed or go beyond something in quality, achievement, or degree.","c":"超越；勝過","s":"Her performance surpassed all expectations, earning her top honors.","t":"她的表現超越了所有人的期望，為她贏得最高榮譽。","src":"306 + 386"},{"w":"surreal","p":"adj.","d":"Having the qualities of a dream or fantasy; strange or unreal in a way that is disorienting.","c":"超現實的；夢幻般的；離奇的","s":"The scene felt surreal, as if it were taken from a dream rather than reality.","t":"這個場景感覺很超現實，彷彿來自夢境而非現實。","src":"306"},{"w":"surrender","p":"v.","d":"To give up or yield.","c":"投降；放棄","s":"The weakened army surrendered to the enemy.","t":"衰弱的軍隊向敵人投降了。","src":"386"},{"w":"surreptitious","p":"adj.","d":"Kept secret, especially because it would not be approved of.","c":"鬼鬼祟祟的；暗中的","s":"The surreptitious meeting was held in a hidden location to avoid detection.","t":"這場祕密會議在隱密的地點舉行，以免被發現。","src":"306"},{"w":"susceptible","p":"adj.","d":"Easily influenced or affected.","c":"易受影響的","s":"With his weakened immune system, Marcelo is susceptible to illness.","t":"由於免疫系統虛弱，馬塞羅很容易生病。","src":"386"},{"w":"synchronization","p":"n.","d":"The process of coordinating events.","c":"同步；同步化","s":"The synchronization of lights helped traffic flow.","t":"燈號的同步讓交通更加順暢。","src":"386"},{"w":"synchronize","p":"v.","d":"To cause things to happen or operate at the same time or rate.","c":"使同步；使同時發生","s":"They tried to synchronize their watches to ensure they all arrived on time.","t":"他們試著把手錶對時，以確保大家都能準時抵達。","src":"306"}]},{"unit":28,"theme":"tactile – unanimous","cards":[{"w":"tactile","p":"adj.","d":"Relating to or involving the sense of touch.","c":"觸覺的","s":"The tactile texture of the sculpture was intriguing to the audience.","t":"雕塑的觸感質地引起了觀眾的興趣。","src":"306"},{"w":"tangible","p":"adj.","d":"Perceptible by touch; capable of being touched or felt.","c":"有形的；實體的；可感知的","s":"The evidence was tangible and could be held in our hands.","t":"這項證據是有形的，可以握在手中。","src":"306"},{"w":"tedious","p":"adj.","d":"Too long, slow, or dull; tiresome and repetitive.","c":"冗長乏味的","s":"The process of reviewing the long report was tedious, but necessary.","t":"審閱那份冗長報告的過程很乏味，卻是必要的。","src":"306"},{"w":"temerity","p":"n.","d":"Excessive confidence or boldness, often causing rash actions.","c":"魯莽；冒失","s":"She had the temerity to question her teacher’s authority in front of the class.","t":"她竟然膽敢在全班面前質疑老師的權威。","src":"306"},{"w":"tenacious","p":"adj.","d":"Holding firm to a belief, goal, or course of action; persistent.","c":"頑強的；堅持不懈的","s":"The tenacious athlete continued to train despite the setbacks.","t":"那位堅韌的運動員儘管遭遇挫折，仍繼續訓練。","src":"306"},{"w":"tentative","p":"adj.","d":"Uncertain or not fully decided.","c":"試探性的；暫定的；猶豫的","s":"Our plans are tentative and may change.","t":"我們的計畫還是暫定的，可能會改變。","src":"386"},{"w":"tenuous","p":"adj.","d":"Very weak or slight; lacking substance or strength.","c":"脆弱的；薄弱的","s":"The link between the two events was tenuous at best, with little evidence to support it.","t":"這兩件事之間的關聯頂多很薄弱，幾乎沒有證據支持。","src":"306 + 386"},{"w":"terse","p":"adj.","d":"Concise and to the point, often to the point of rudeness.","c":"簡潔的；扼要的","s":"His terse response left no room for further discussion.","t":"他簡短生硬的回答讓人沒有再討論的餘地。","src":"306"},{"w":"theoretical","p":"adj.","d":"Based on theory rather than practice.","c":"理論上的","s":"The idea remains theoretical until tested.","t":"在經過測試之前，這個想法仍然只是理論上的。","src":"386"},{"w":"theory","p":"n.","d":"A system of ideas intended to explain something.","c":"理論","s":"Einstein's theory of relativity changed physics.","t":"愛因斯坦的相對論改變了物理學。","src":"386"},{"w":"thoughtfulness","p":"n.","d":"Consideration for others.","c":"體貼；周到","s":"Her thoughtfulness made her a great friend.","t":"她的體貼讓她成為很棒的朋友。","src":"386"},{"w":"thwart","p":"v.","d":"To prevent someone from accomplishing something; to obstruct.","c":"阻撓；妨礙","s":"The storm thwarted our plans to go sailing on the lake.","t":"暴風雨阻撓了我們去湖上划船的計畫。","src":"306"},{"w":"tranquil","p":"adj.","d":"Free from disturbance; calm and peaceful.","c":"寧靜的；平靜的","s":"The tranquil park was the perfect place to relax and reflect.","t":"寧靜的公園是放鬆和沉思的完美地點。","src":"306 + 386"},{"w":"transcend","p":"v.","d":"To rise above or go beyond the limits of something, often in a spiritual or abstract way.","c":"超越；勝過","s":"Her creativity transcended the boundaries of traditional art.","t":"她的創造力超越了傳統藝術的界限。","src":"306"},{"w":"transform","p":"v.","d":"To change in form or appearance.","c":"改變；轉化；改造","s":"The caterpillar transformed into a butterfly.","t":"毛毛蟲蛻變成了蝴蝶。","src":"386"},{"w":"trepidation","p":"n.","d":"A feeling of fear or anxiety about something that may happen.","c":"恐懼；憂慮","s":"The thought of speaking in front of a large crowd filled him with trepidation.","t":"一想到要在一大群人面前演講，他就充滿了惶恐。","src":"306"},{"w":"trite","p":"adj.","d":"Lacking originality or freshness; overused and uninteresting.","c":"陳腐的；老套的","s":"His trite comments on the topic did nothing to advance the conversation.","t":"他對這個話題陳腔濫調的評論對推進對話毫無幫助。","src":"306"},{"w":"ubiquitous","p":"adj.","d":"Present, appearing, or found everywhere.","c":"無所不在的；普遍的","s":"Smartphones are ubiquitous in modern society, seen in almost every hand.","t":"智慧型手機在現代社會無所不在，幾乎人手一支。","src":"306 + 386"},{"w":"unanimous","p":"adj.","d":"Fully in agreement, especially by all members of a group.","c":"一致同意的","s":"The decision was unanimous, with everyone agreeing on the solution.","t":"這項決定是全體一致通過的，每個人都同意這個解決辦法。","src":"306"}]},{"unit":29,"theme":"uncanny – variable","cards":[{"w":"uncanny","p":"adj.","d":"Strange or mysterious, often in a way that causes unease.","c":"離奇的；詭異的","s":"The uncanny silence in the room made everyone feel uneasy.","t":"房間裡詭異的寂靜讓每個人都很不安。","src":"306"},{"w":"uncontroversial","p":"adj.","d":"Not likely to cause disagreement.","c":"無爭議的","s":"The decision was uncontroversial and widely accepted.","t":"這項決定沒有爭議，廣為大眾接受。","src":"386"},{"w":"unctuous","p":"adj.","d":"Excessively flattering or ingratiating, often insincerely so.","c":"諂媚的；油腔滑調的","s":"His unctuous compliments made everyone feel uncomfortable.","t":"他油腔滑調的恭維讓每個人都不舒服。","src":"306"},{"w":"undeniable","p":"adj.","d":"Cannot be disputed.","c":"不可否認的","s":"Simone Biles' talent as a gymnast is undeniable.","t":"西蒙・拜爾斯身為體操選手的天分是無可否認的。","src":"386"},{"w":"undermine","p":"v.","d":"To weaken or damage something gradually or covertly.","c":"逐漸削弱；暗中破壞","s":"The constant criticism undermined her confidence.","t":"不斷的批評削弱了她的自信。","src":"306"},{"w":"underscore","p":"v.","d":"To emphasize or highlight something, usually to draw attention to its importance.","c":"強調","s":"The speaker underscored the need for immediate action in the closing remarks.","t":"演講者在結語中強調了立即行動的必要。","src":"306 + 386"},{"w":"unequivocal","p":"adj.","d":"Leaving no doubt; clear and unambiguous.","c":"明確的；毫不含糊的","s":"His response was unequivocal, leaving no room for misinterpretation.","t":"他的回答明確無誤，沒有被誤解的空間。","src":"306"},{"w":"unimportant","p":"adj.","d":"Not significant.","c":"不重要的","s":"The details were unimportant to the main issue.","t":"這些細節對主要問題並不重要。","src":"386"},{"w":"unintended","p":"adj.","d":"Not planned or meant.","c":"非故意的；意外的","s":"The side effects of the medication were unintended.","t":"這種藥物的副作用並非原本所預期的。","src":"386"},{"w":"universal","p":"adj.","d":"Common to all.","c":"普遍的；全宇宙的；通用的","s":"The desire for love is universal.","t":"對愛的渴望是普世共通的。","src":"386"},{"w":"unmistakable","p":"adj.","d":"Clearly recognizable.","c":"明確無誤的；顯而易見的","s":"Morgan Freeman's voice is unmistakable.","t":"摩根・費里曼的聲音一聽就認得出來。","src":"386"},{"w":"unobtrusive","p":"adj.","d":"Not conspicuous or attracting attention; not noticeable.","c":"不張揚的；不顯眼的；不引人注目的","s":"The waiter was unobtrusive, ensuring we had everything we needed without being noticed.","t":"服務生毫不打擾，在不被注意的情況下確保我們需要的一切都有了。","src":"306 + 386"},{"w":"unoriginal","p":"adj.","d":"Lacking originality.","c":"缺乏創意的；老套的","s":"His speech was unoriginal and predictable.","t":"他的演講毫無新意又可以預料。","src":"386"},{"w":"unpredictable","p":"adj.","d":"Difficult to foresee.","c":"難以預測的","s":"The weather in winter can often be unpredictable.","t":"冬天的天氣常常難以預測。","src":"386"},{"w":"uproarious","p":"adj.","d":"Characterized by loud noise or laughter; very funny.","c":"喧鬧的；爆笑的","s":"The comedian’s uproarious performance had the audience in stitches.","t":"那位喜劇演員令人捧腹的表演讓觀眾笑得前俯後仰。","src":"306"},{"w":"vacillate","p":"v.","d":"To waver between different opinions or actions; to be indecisive.","c":"猶豫不決；搖擺","s":"He vacillated between accepting the job offer and staying at his current position.","t":"他在接受這份工作與留在目前職位之間猶豫不決。","src":"306"},{"w":"vague","p":"adj.","d":"Not clear in meaning or expression; indefinite.","c":"模糊的；含糊的","s":"The instructions were vague, leaving us uncertain about the next step.","t":"說明含糊不清，讓我們不確定下一步該怎麼做。","src":"306"},{"w":"validate","p":"adj.","d":"To confirm or verify as being true, accurate, or acceptable.","c":"證實；驗證","s":"The results were validated by an independent review panel before publication.","t":"研究結果在發表前經過獨立審查小組的驗證。","src":"306 + 386"},{"w":"variable","p":"adj.","d":"Likely to change.","c":"多變的；易變的","s":"The weather is highly variable in spring.","t":"春天的天氣變化多端。","src":"386"}]},{"unit":30,"theme":"vary – zenith","cards":[{"w":"vary","p":"v.","d":"To change or differ in some way; to alter or modify.","c":"改變；不同","s":"The temperature can vary greatly between day and night in the desert.","t":"沙漠中的日夜溫差可能非常大。","src":"306"},{"w":"vehement","p":"adj.","d":"Showing strong feeling or passion; forceful or intense.","c":"強烈的；激烈的","s":"He spoke with vehement anger during the debate.","t":"他在辯論中帶著激烈的怒氣發言。","src":"306"},{"w":"verisimilitude","p":"n.","d":"The appearance or quality of being real or true; the resemblance to reality.","c":"逼真；擬真性","s":"The movie’s attention to detail gave it a sense of verisimilitude that captivated the audience.","t":"這部電影對細節的講究賦予它一種逼真感，深深吸引了觀眾。","src":"306 + 386"},{"w":"veritable","p":"adj.","d":"Used to emphasize truth.","c":"名副其實的；真正的","s":"Einstein was a veritable genius.","t":"愛因斯坦是一位名副其實的天才。","src":"386"},{"w":"vex","p":"v.","d":"To annoy or worry someone; to cause distress.","c":"使煩惱；使苦惱","s":"The constant noise began to vex the students trying to concentrate.","t":"持續不斷的噪音開始讓努力專心的學生感到煩躁。","src":"306"},{"w":"vigilance","p":"n.","d":"The action of keeping careful watch.","c":"警覺；警戒","s":"Constant vigilance is needed for security.","t":"維護安全需要時時保持警覺。","src":"386"},{"w":"vindicate","p":"v.","d":"To clear someone of blame or suspicion; to justify or prove something right.","c":"證明清白；證明…正確","s":"The evidence finally vindicated him and proved his innocence.","t":"證據終於還他清白，證明了他的無辜。","src":"306"},{"w":"virtuous","p":"adj.","d":"Having high moral standards; righteous.","c":"有美德的；正直的","s":"The virtuous knight always helped those in need.","t":"那位品德高尚的騎士總是幫助有需要的人。","src":"306"},{"w":"vital","p":"adj.","d":"Urgently necessary.","c":"至關重要的","s":"It is vital that you respond by the deadline.","t":"你務必在截止期限前回覆。","src":"386"},{"w":"volatile","p":"adj.","d":"Liable to change rapidly and unpredictably, especially for the worse; highly unstable.","c":"易變的；不穩定的；揮發性的","s":"The volatile stock market caused many investors to panic.","t":"動盪不定的股市讓許多投資人陷入恐慌。","src":"306 + 386"},{"w":"waive","p":"v.","d":"To voluntarily give up or relinquish a right or claim.","c":"放棄(權利)","s":"He decided to waive his right to a trial and accepted the settlement offer.","t":"他決定放棄接受審判的權利，接受了和解提議。","src":"306 + 386"},{"w":"warranted","p":"adj.","d":"Justified or deserved; reasonable.","c":"有正當理由的；合理的","s":"Her frustration was warranted after the long wait for assistance.","t":"在漫長地等待協助之後，她的沮喪是有道理的。","src":"306 + 386"},{"w":"wayward","p":"adj.","d":"Difficult to control or predict, especially due to unusual or unpredictable behavior.","c":"任性的；難以駕馭的","s":"The wayward child refused to follow the rules.","t":"那個任性的孩子拒絕遵守規則。","src":"306"},{"w":"widespread","p":"adj.","d":"Found or occurring over a large area.","c":"普遍的；廣泛的","s":"The disease became widespread.","t":"這種疾病變得廣泛流行。","src":"386"},{"w":"winsome","p":"adj.","d":"Attractive or appealing in a charming or pleasing way.","c":"迷人的；討人喜歡的","s":"Her winsome smile made her instantly likable.","t":"她迷人的微笑讓人立刻對她產生好感。","src":"306"},{"w":"wistful","p":"adj.","d":"Longing or yearning for something that may never be attained; melancholic.","c":"渴望的；惆悵的","s":"He felt wistful as he looked at the old photograph of his childhood home.","t":"看著兒時老家的舊照片，他感到悵然若失。","src":"306"},{"w":"withdraw","p":"v.","d":"To remove or retreat.","c":"撤回；退出","s":"She withdrew from the competition.","t":"她退出了比賽。","src":"386"},{"w":"zealous","p":"adj.","d":"Showing great energy or enthusiasm in pursuit of a cause or objective.","c":"熱心的；狂熱的","s":"The zealous volunteers worked tirelessly to support the cause.","t":"熱心的志工們不辭辛勞地支持這項理念。","src":"306"},{"w":"zenith","p":"n.","d":"The highest point or peak; the culmination.","c":"頂點；鼎盛時期","s":"The company reached its zenith with record profits last year.","t":"這家公司去年以創紀錄的利潤達到了巔峰。","src":"306"}]}];
